class PoFileFormatTests(SimpleTestCase):
    """The docker build runs compilemessages, whose msgfmt --check-format
    rejects a bare % in a msgstr whose msgid uses %%."""

    @unittest.skipIf(shutil.which('msgfmt') is None, 'msgfmt not installed')
    def test_every_po_passes_msgfmt_check_format(self):
        locale_dir = os.path.join(os.path.dirname(__file__), '..', 'locale')
        po_files = glob.glob(os.path.join(locale_dir, '*', 'LC_MESSAGES', '*.po'))
        self.assertTrue(po_files, msg='no .po files found')
        for po in po_files:
            with self.subTest(po=os.path.relpath(po, locale_dir)):
                proc = subprocess.run(
                    ['msgfmt', '--check-format', '-o', os.devnull, po],
                    capture_output=True, text=True)
                self.assertEqual(proc.returncode, 0, msg=proc.stderr[:2000])


class OfficialSiteUrlTests(SimpleTestCase):
    """Internal encyclopedia URLs should stay readable for localized names."""

    def test_internal_links_transliterate_accented_names(self):
        from chardata.official_site import (
            get_item_link,
            get_monster_link,
            get_resource_link,
            get_set_link,
        )
        self.assertEqual(
            get_item_link('equipment', 999, "Épée d'Âme"),
            '/encyclopedia/item/equipment/999-epee-d-ame/')
        self.assertEqual(
            get_resource_link('resources', 395, 'Trèfle à 5 feuilles', 'retro'),
            '/retro/encyclopedia/resource/resources/395-trefle-a-5-feuilles/')
        self.assertEqual(
            get_monster_link(123, 'Jalató Real', 'retro'),
            '/retro/encyclopedia/monster/123-jalato-real/')
        self.assertEqual(
            get_set_link(321, 'Panoplie du Bouftou Royal', 'retro'),
            '/retro/encyclopedia/set/321-panoplie-du-bouftou-royal/')


class EmailTemplateTranslationTests(SimpleTestCase):
    """A blocktrans whose text drifts from its .po msgid falls back to English
    silently. Reads the committed .po, not the compiled .mo."""

    LANGS = ('fr', 'es', 'pt', 'de')

    @staticmethod
    def _blocktrans_msgids(text):
        # Plain {% blocktrans %} only: no email template uses the
        # with/count/trimmed variants.
        blocks = re.findall(
            r'\{%\s*blocktrans\s*%\}(.*?)\{%\s*endblocktrans\s*%\}', text, re.DOTALL)
        return [re.sub(r'\{\{\s*(\w+)\s*\}\}', r'%(\1)s', b) for b in blocks]

    def test_email_blocktrans_are_translated(self):
        try:
            import polib
        except ImportError:
            self.skipTest('polib not installed')
        email_dir = os.path.join(
            os.path.dirname(__file__), 'templates', 'chardata', 'emails')
        templates = glob.glob(os.path.join(email_dir, '*'))
        self.assertTrue(templates, msg='no email templates found')
        catalogs = {}
        for lang in self.LANGS:
            path = os.path.join(os.path.dirname(__file__), '..', 'locale',
                                lang, 'LC_MESSAGES', 'django.po')
            catalogs[lang] = {e.msgid: e for e in polib.pofile(path)
                              if not e.obsolete}
        for tpl in templates:
            with open(tpl, encoding='utf-8') as fh:
                text = fh.read()
            for msgid in self._blocktrans_msgids(text):
                for lang in self.LANGS:
                    entry = catalogs[lang].get(msgid)
                    self.assertIsNotNone(entry, msg=(
                        '%s: blocktrans has no active %s msgid, so it falls back '
                        'to English. Resync the .po with the template: %r'
                        % (os.path.basename(tpl), lang, msgid[:90])))
                    self.assertTrue(entry.msgstr.strip(), msg=(
                        '%s: %s translation is empty for %r'
                        % (os.path.basename(tpl), lang, msgid[:90])))


class TemplateTranslationCoverageTests(SimpleTestCase):
    """Every string a template asks for, in all four catalogs, translated.

    The guard above walks only `templates/chardata/emails`, so a blocktrans
    anywhere else fell back to English with nothing to say so. Widening it was
    free on the day it was written because the population was already clean:
    1388 string requests over 90 templates, and the single absence was the
    string /infeasible/ had gained the same afternoon. Widening a guard over a
    dirty population is a project; over a clean one it is just holding the line.

    Three things it has to get right, each of which made the measuring script
    lie before this was written:
      - a literal % is stored %% in a python-format msgid, so
        "100% translation coverage" reads as missing unless the key is
        unescaped first;
      - `{% trans '...' %}` with single quotes covers 156 tags here, and a
        pattern that reads only double quotes answers cleanly about a
        population it never looked at;
      - a `count` blocktrans keeps its singular before `{% plural %}` and its
        translation in msgstr_plural rather than msgstr.
    """

    LANGS = ('fr', 'es', 'pt', 'de')

    BLOCK = re.compile(
        r'\{%\s*blocktrans(?:late)?([^%]*)%\}(.*?)'
        r'\{%\s*endblocktrans(?:late)?\s*%\}', re.DOTALL)
    TRANS = re.compile(
        r'''\{%\s*trans(?:late)?\s+(?:"((?:[^"\\]|\\.)*)"'''
        r"""|'((?:[^'\\]|\\.)*)')""")
    PLURAL = re.compile(r'\{%\s*plural\s*%\}')

    # One witness per trap rather than one per catalog. A positive control that
    # only exercises the easy case inspires exactly the confidence of a real
    # one, which is what makes it dangerous: the percent witness is here
    # because its absence is what let the script call a translated string
    # missing.
    WITNESSES = (
        ('plain string',
         'Remove or lower <a href=%(mins_link)s>minimum characteristics</a> '
         'and raise their <a href=%(weights_link)s>weights</a> instead'),
        ('literal percent',
         '100% translation coverage for all 5 supported languages '
         '(en, fr, de, es, pt)'),
    )

    @classmethod
    def _msgids(cls, text):
        for opts, body in cls.BLOCK.findall(text):
            if 'count' in opts:
                body = cls.PLURAL.split(body)[0]
            renames = dict(re.findall(r'([\w.]+)\s+as\s+(\w+)', opts))
            body = re.sub(
                r'\{\{\s*([\w.]+)\s*\}\}',
                lambda m: '%%(%s)s' % renames.get(m.group(1), m.group(1)), body)
            if 'trimmed' in opts:
                body = ' '.join(body.split())
            yield body
        for double, single in cls.TRANS.findall(text):
            yield (double or single).replace('\\"', '"').replace("\\'", "'")

    @staticmethod
    def _translated(entry):
        if entry.msgstr.strip():
            return True
        return any(v.strip() for v in (entry.msgstr_plural or {}).values())

    def test_every_template_string_is_in_every_catalog(self):
        try:
            import polib
        except ImportError:
            self.skipTest('polib not installed')
        site = os.path.join(os.path.dirname(__file__), '..')

        catalogs = {}
        for lang in self.LANGS:
            entries = {}
            for entry in polib.pofile(os.path.join(
                    site, 'locale', lang, 'LC_MESSAGES', 'django.po')):
                if entry.obsolete:
                    continue
                entries.setdefault(entry.msgid, entry)
                if '%%' in entry.msgid:
                    entries.setdefault(entry.msgid.replace('%%', '%'), entry)
            catalogs[lang] = entries

        for label, msgid in self.WITNESSES:
            for lang in self.LANGS:
                entry = catalogs[lang].get(msgid)
                self.assertIsNotNone(entry, msg=(
                    'witness %r is not found in %s, so this test cannot tell a '
                    'clean catalog from a lookup that never matches'
                    % (label, lang)))
                self.assertTrue(self._translated(entry), msg=(
                    'witness %r is untranslated in %s' % (label, lang)))

        templates = []
        for root, _dirs, files in os.walk(site):
            if os.sep + 'templates' + os.sep not in root + os.sep:
                continue
            templates += [os.path.join(root, name) for name in files
                          if name.endswith(('.html', '.txt'))]
        self.assertGreater(len(templates), 50, msg=(
            'only %d templates walked: a clean answer over a population this '
            'small would mean nothing' % len(templates)))

        for path in templates:
            with open(path, encoding='utf-8') as fh:
                text = fh.read()
            for msgid in self._msgids(text):
                if not msgid.strip():
                    continue
                for lang in self.LANGS:
                    entry = catalogs[lang].get(msgid)
                    self.assertIsNotNone(entry, msg=(
                        '%s: no active %s msgid, so the page falls back to '
                        'English. Resync the .po with the template: %r'
                        % (os.path.basename(path), lang, msgid[:90])))
                    self.assertTrue(self._translated(entry), msg=(
                        '%s: %s translation is empty for %r'
                        % (os.path.basename(path), lang, msgid[:90])))


class BrandNameCatalogTests(SimpleTestCase):
    """Branding rule: "The Dofus Fashionista" in English only; every other
    language uses "Dofus Fashionista" (no "The")."""

    NON_ENGLISH = ('fr', 'es', 'pt', 'de')

    def test_no_the_dofus_fashionista_in_non_english_catalogs(self):
        try:
            import polib
        except ImportError:
            self.skipTest('polib not installed')
        locale_dir = os.path.join(os.path.dirname(__file__), '..', 'locale')
        for lang in self.NON_ENGLISH:
            for po_path in glob.glob(os.path.join(
                    locale_dir, lang, 'LC_MESSAGES', '*.po')):
                po = polib.pofile(po_path)
                offenders = [e.msgid[:60] for e in po
                             if not e.obsolete and e.msgstr
                             and 'The Dofus Fashionista' in e.msgstr]
                with self.subTest(po=os.path.relpath(po_path, locale_dir)):
                    self.assertEqual(offenders, [], msg=(
                        '%s: %d msgstr still say "The Dofus Fashionista"; the '
                        'brand must drop "The" outside English. Offenders: %s'
                        % (lang, len(offenders), offenders)))

    def test_brand_fashionista_is_capitalized(self):
        try:
            import polib
        except ImportError:
            self.skipTest('polib not installed')
        locale_dir = os.path.join(os.path.dirname(__file__), '..', 'locale')
        for po_path in glob.glob(os.path.join(
                locale_dir, '*', 'LC_MESSAGES', '*.po')):
            po = polib.pofile(po_path)
            offenders = [e.msgid[:60] for e in po
                         if not e.obsolete and e.msgstr
                         and re.search(r'[Dd]ofus fashionista', e.msgstr)]
            with self.subTest(po=os.path.relpath(po_path, locale_dir)):
                self.assertEqual(offenders, [], msg=(
                    '%s: brand must be "Dofus Fashionista" (capital F). '
                    'Offenders: %s' % (po_path, offenders)))


class TranslationRegressionTests(SimpleTestCase):
    """A fuzzy or empty .po entry is ignored by Django and falls back to
    English, so these assert the translated output across fr/es/pt/de."""

    def test_charged_n_times_fr(self):
        with translation.override('fr'):
            self.assertEqual(gettext('Charged 3 times'), 'Chargée 3 fois')
            self.assertEqual(gettext('Charged 12 times'), 'Chargée 12 fois')

    def test_touch_set_bonus_condition_shows_lt_2(self):
        # Touch trophies cap at 1 set bonus, so their condition line reads
        # "< 2"; dofus3 and the beta stay "< 3".
        from chardata.solution_result import LightSetConditionLine
        with translation.override('fr'):
            self.assertEqual(LightSetConditionLine(None, 1).text, 'Bonus de panoplies < 2')
            self.assertEqual(LightSetConditionLine(None, 2).text, 'Bonus de panoplies < 3')

    def test_the_offline_page_speaks_the_reader_s_language(self):
        # It lived as a raw HTML string in urls.py, outside every catalogue.
        expected = {'fr': 'Tu es hors connexion', 'es': 'Estás sin conexión',
                    'pt': 'Você está sem conexão', 'de': 'Du bist offline'}
        for language, text in expected.items():
            with translation.override(language):
                self.assertEqual(gettext('You are offline'), text)

    def test_the_discord_call_to_action_is_translated(self):
        expected = {'fr': 'Rejoins notre Discord !',
                    'es': '¡Únete a nuestro Discord!',
                    'pt': 'Entra no nosso Discord!',
                    'de': 'Tritt unserem Discord bei!'}
        for language, text in expected.items():
            with translation.override(language):
                self.assertEqual(gettext('Join our Discord!'), text)

    def test_german_mp_is_bp_not_member_of_parliament(self):
        with translation.override('de'):
            self.assertEqual(gettext('MP'), 'BP')

    def test_steals_mp_translated_per_language(self):
        expected = {'fr': 'Vole 3 PM', 'es': 'Roba 3 PM',
                    'pt': 'Rouba 3 PM', 'de': 'Stiehlt 3 BP'}
        for lang, exp in expected.items():
            with translation.override(lang):
                self.assertEqual(gettext('Steals %(mp)d MP') % {'mp': 3}, exp,
                                 msg='Steals MP wrong for %s' % lang)

    def test_removes_ap_translated_per_language(self):
        expected = {'fr': 'Retire 3 PA', 'es': 'Quita 3 PA',
                    'pt': 'Remove 3 PA', 'de': 'Entzieht 3 AP'}
        for lang, exp in expected.items():
            with translation.override(lang):
                self.assertEqual(gettext('Removes %(ap)d AP') % {'ap': 3}, exp,
                                 msg='Removes AP wrong for %s' % lang)

    def test_removes_mp_translated_per_language(self):
        expected = {'fr': 'Retire 3 PM', 'es': 'Quita 3 PM',
                    'pt': 'Remove 3 PM', 'de': 'Entzieht 3 BP'}
        for lang, exp in expected.items():
            with translation.override(lang):
                self.assertEqual(gettext('Removes %(mp)d MP') % {'mp': 3}, exp,
                                 msg='Removes MP wrong for %s' % lang)

    def test_the_weapon_removal_hits_are_translated(self):
        # These two sit on a weapon's damage line, and they were the only
        # runtime-translated data strings left in English in every language.
        expected = {
            '(removes ap)': {'fr': '(retire PA)', 'es': '(quita PA)',
                             'pt': '(remove PA)', 'de': '(entzieht AP)'},
            '(removes mp)': {'fr': '(retire PM)', 'es': '(quita PM)',
                             'pt': '(remove PM)', 'de': '(entzieht BP)'},
        }
        for source, per_language in expected.items():
            for language, want in per_language.items():
                with translation.override(language):
                    self.assertEqual(gettext(source), want,
                                     msg='%s wrong for %s' % (source, language))

    def test_every_runtime_translated_data_string_is_answered(self):
        # The catalogs are what turns data into the reader's language; a blank
        # entry shows the raw English on the page.
        import ast
        from fashionistapulp.fashionista_config import get_fashionista_path
        path = os.path.join(get_fashionista_path(), 'fashionsite', 'chardata',
                            'dynamic_translations.py')
        with open(path, encoding='utf-8') as handle:
            tree = ast.parse(handle.read())
        strings = [node.args[0].value for node in ast.walk(tree)
                   if isinstance(node, ast.Call)
                   and getattr(node.func, 'id', '') == 'gettext_noop'
                   and node.args and isinstance(node.args[0], ast.Constant)]
        self.assertGreater(len(strings), 100)
        for language in ('fr', 'es', 'pt', 'de'):
            with translation.override(language):
                blank = [s for s in strings if not gettext(s).strip()]
            with self.subTest(language=language):
                self.assertEqual(blank, [], language)

    def test_previously_untranslated_ui_strings(self):
        expected = {
            'Hunting Weapon': {'fr': 'Arme de chasse', 'es': 'Arma de caza',
                               'pt': 'Arma de caça', 'de': 'Jagdwaffe'},
            'Linked to the character': {'fr': 'Lié au personnage',
                                        'es': 'Vinculado al personaje',
                                        'pt': 'Vinculado ao personagem',
                                        'de': 'Mit dem Charakter verknüpft'},
        }
        for msgid, per_lang in expected.items():
            for lang, exp in per_lang.items():
                with translation.override(lang):
                    self.assertEqual(gettext(msgid), exp,
                                     msg='%r wrong for %s' % (msgid, lang))


class StructureSetResolutionTests(SimpleTestCase):
    """get_set_by_id must return the bonus-bearing set, not a synthetic touch set
    sharing its id: 1 is the dofus3 "Gobball Set" and the touch "Jellix Set"."""

    def test_get_set_by_id_prefers_real_bonus_set(self):
        from fashionistapulp.structure import get_structure
        s = get_structure()
        got = s.get_set_by_id(1)
        self.assertIs(got, s.sets_dict.get(1))
        self.assertTrue(got.bonus, 'set 1 should expose its bonuses')


class BreadcrumbJsonLdTests(SimpleTestCase):
    """The breadcrumb JSON-LD is embedded in a <script> via |safe, so it must escape
    characters that could break out of the tag."""

    def test_escapes_script_breakout(self):
        import json
        from chardata.encyclopedia_view import _breadcrumb_jsonld
        out = _breadcrumb_jsonld([('a</script><img src=x>', 'https://x/')])
        self.assertNotIn('</script>', out)
        self.assertNotIn('<img', out)
        self.assertIn('\\u003c', out)
        self.assertEqual(json.loads(out)['itemListElement'][0]['name'],
                         'a</script><img src=x>')

    def test_every_page_with_crumbs_carries_the_markup(self):
        """The two index pages showed a crumb trail no search engine could read,
        while the five detail pages next to them marked theirs up."""
        import os
        import re
        here = os.path.join(os.path.dirname(__file__), 'templates', 'chardata')
        missing = []
        for name in sorted(os.listdir(here)):
            if not name.startswith('encyclopedia'):
                continue
            body = io.open(os.path.join(here, name), encoding='utf-8').read()
            if not re.search(r'<nav class="encyclopedia-crumbs"', body):
                continue
            if 'breadcrumb_jsonld' not in body:
                missing.append(name)
        self.assertEqual([], missing)


# Plain (non-manifest) static storage: the test runner forces DEBUG=False, and
# settings would then make {% static %} require a collectstatic manifest.
@override_settings(
    STORAGES={
        'default': {'BACKEND': 'django.core.files.storage.FileSystemStorage'},
        'staticfiles': {'BACKEND': 'django.contrib.staticfiles.storage.StaticFilesStorage'},
    }
)
class PublicRouteSmokeTests(TestCase):
    """Key public routes resolve and return the expected status codes."""

    def test_setup_links_the_class_guide(self):
        resp = self.client.get('/setup/')
        self.assertEqual(resp.status_code, 200)
        self.assertContains(resp, 'href="/guides/choosing-your-class/"')
        with translation.override('fr'):
            expected = translation.gettext(
                'Not sure which class to pick? Read the guide')
        self.assertNotEqual(
            expected, 'Not sure which class to pick? Read the guide',
            'fr catalog entry missing')
        resp = self.client.get('/setup/', HTTP_ACCEPT_LANGUAGE='fr')
        self.assertContains(resp, expected)

    def test_search_finds_resources(self):
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path
        for version, prefix in (('dofus3', ''), ('beta', '/beta'),
                                ('touch', '/touch'), ('retro', '/retro'),
                                ('dofus2', '/dofus2')):
            with self.subTest(version=version):
                conn = sqlite3.connect(get_items_db_path(version))
                row = conn.execute(
                    "SELECT name FROM item_recipe_ingredient_names "
                    "WHERE language = 'en' AND ingredient_subtype = 'resources' "
                    "ORDER BY ingredient_ankama_id LIMIT 1").fetchone()
                conn.close()
                self.assertIsNotNone(row, 'no resource ingredient for ' + version)
                resp = self.client.get('%s/encyclopedia/' % prefix, {'q': row[0]})
                self.assertEqual(resp.status_code, 200)
                self.assertContains(resp, 'encyclopedia-resource-hit')
                self.assertContains(resp, '%s/encyclopedia/resource/' % prefix)

    def test_search_family_nav_links_each_result_family(self):
        # The anchored count bar is for multi-family searches only: plain
        # browsing, with no query, never shows it.
        resp = self.client.get('/retro/encyclopedia/', {'q': 'bouftou'},
                               HTTP_ACCEPT_LANGUAGE='fr')
        self.assertEqual(resp.status_code, 200)
        body = resp.content.decode('utf-8')
        self.assertIn('class="encyclopedia-family-nav"', body)
        for anchor in ('#resources-results', '#monsters-results',
                       '#items-results'):
            self.assertIn('href="%s"' % anchor, body)
        for section_id in ('id="resources-results"', 'id="monsters-results"',
                           'id="items-results"'):
            self.assertIn(section_id, body)
        resp = self.client.get('/encyclopedia/')
        self.assertNotIn('class="encyclopedia-family-nav"',
                         resp.content.decode('utf-8'))

    def test_search_totals_are_real_not_capped(self):
        from chardata import encyclopedia_view as ev

        # A one-letter needle overflows the display cap: the entries stay
        # capped, the total does not.
        entries, total = ev._search_resources('retro', 'e', 'en')
        self.assertLessEqual(len(entries), 48)
        self.assertGreater(total, 12)
        self.assertGreaterEqual(total, len(entries))

        # On the page, the section header carries the real total and the chips
        # past the first 12 fold behind a details block.
        needle = ev._normalized_text('bouftou')
        _entries, res_total = ev._search_resources('retro', needle, 'fr')
        resp = self.client.get('/retro/encyclopedia/', {'q': 'bouftou'},
                               HTTP_ACCEPT_LANGUAGE='fr')
        self.assertEqual(resp.status_code, 200)
        body = resp.content.decode('utf-8')
        m = re.search(r'id="resources-results">[^<]*?(\d+)<', body)
        self.assertIsNotNone(m, 'resources header missing')
        self.assertEqual(int(m.group(1)), res_total)
        if res_total > 12:
            self.assertIn('class="encyclopedia-hits-more"', body)

