class RegistrationFunnelTests(TestCase):
    """End-to-end signup: register -> inactive user + confirmation email ->
    following the emailed link activates the account."""

    def setUp(self):
        # Registration checks recaptcha with a live Google call; pass it.
        from unittest import mock
        patcher = mock.patch('chardata.login_view.recaptcha_ok',
                             return_value=True)
        patcher.start()
        self.addCleanup(patcher.stop)

    def test_register_confirm_activates_account(self):
        from django.contrib.auth.models import User
        from django.core import mail
        resp = self.client.post('/register/', {
            'username': 'newplayer', 'password': 'a-solid-password-42',
            'email': 'newplayer@test.local'})
        self.assertEqual(resp.status_code, 302)
        user = User.objects.get(username='newplayer')
        self.assertFalse(user.is_active, 'account must start inactive')
        self.assertEqual(len(mail.outbox), 1)
        m = re.search(r'/confirm_email/[^/\s]+/[^/\s]+/', mail.outbox[0].body)
        self.assertIsNotNone(m, 'confirmation link missing from the email')
        resp = self.client.get(m.group(0))
        user.refresh_from_db()
        self.assertTrue(user.is_active, 'confirmation link must activate')

    def test_bad_confirmation_token_rejected(self):
        from django.contrib.auth.models import User
        self.client.post('/register/', {
            'username': 'otherplayer', 'password': 'a-solid-password-42',
            'email': 'otherplayer@test.local'})
        resp = self.client.get('/confirm_email/otherplayer/wrongtoken/')
        user = User.objects.get(username='otherplayer')
        self.assertFalse(user.is_active, 'bad token must not activate')

    def test_welcome_email_follows_request_language(self):
        from django.core import mail
        resp = self.client.post('/register/', {
            'username': 'joueurfr', 'password': 'a-solid-password-42',
            'email': 'joueurfr@test.local'},
            headers={'accept-language': 'fr'})
        self.assertEqual(resp.status_code, 302)
        self.assertEqual(len(mail.outbox), 1)
        self.assertIn('Bienvenue', mail.outbox[0].subject)
        self.assertNotIn('Please click', mail.outbox[0].body)


class ContactFormTests(TestCase):
    """DEBUG=True (the test settings) bypasses the contact captcha."""

    def test_contact_page_renders(self):
        self.assertEqual(self.client.get('/contact/').status_code, 200)

    def test_send_email_delivers_and_redirects(self):
        from django.core import mail
        from unittest import mock
        self.enterContext(mock.patch('chardata.contact_view.recaptcha_ok',
                                     return_value=True))
        resp = self.client.post('/send/', {
            'topic': 'Bug report', 'message': 'The optimizer ate my hat.',
            'email': 'player@test.local', 'name': 'A player'})
        self.assertEqual(resp.status_code, 302)
        self.assertIn('thankyou', resp.url)
        self.assertEqual(len(mail.outbox), 1)
        self.assertIn('Fashionista Form: Bug report', mail.outbox[0].subject)

    def test_send_email_get_redirects_to_contact(self):
        resp = self.client.get('/send/')
        self.assertEqual(resp.status_code, 302)

    def _post(self, **fields):
        from unittest import mock
        self.enterContext(mock.patch('chardata.contact_view.recaptcha_ok',
                                     return_value=True))
        payload = {'topic': 'Bug report', 'message': 'The optimizer ate my hat.',
                   'email': 'player@test.local', 'name': 'A player'}
        payload.update(fields)
        return self.client.post('/send/', payload)

    def test_an_empty_submission_is_not_mailed(self):
        # Four of these reached the inbox as "Fashionista Form:" with an empty
        # body, because the view read POST directly and never validated it.
        from django.core import mail
        for blank in ({'topic': ''}, {'message': ''},
                      {'topic': '   ', 'message': '  '}):
            with self.subTest(blank=blank):
                response = self._post(**blank)
                self.assertEqual(302, response.status_code)
                self.assertIn('nomessage', response.url)
                self.assertEqual([], mail.outbox)

    def test_an_oversized_field_is_not_mailed(self):
        from django.core import mail
        for oversized in ({'topic': 'x' * 201}, {'name': 'x' * 101},
                          {'email': 'x' * 250 + '@test.local'},
                          {'message': 'x' * 10001}):
            with self.subTest(field=list(oversized)[0]):
                response = self._post(**oversized)
                self.assertIn('nomessage', response.url)
                self.assertEqual([], mail.outbox)

    def test_an_unusable_address_is_flagged_not_dropped(self):
        from django.core import mail
        response = self._post(email='not-an-email')
        self.assertIn('thankyou', response.url)
        self.assertEqual(1, len(mail.outbox))
        self.assertIn('not-an-email (not a usable address)', mail.outbox[0].body)

    def test_a_signed_in_reader_is_not_asked_for_their_address(self):
        from django.contrib.auth.models import User
        from chardata.models import UserAlias
        user = User.objects.create_user('Freuzz', 'freuzz@test.local', 'pw-1234')
        alias = UserAlias(user=user, alias='Freuzz')
        alias.save()
        self.client.force_login(user)
        response = self.client.get('/contact/', HTTP_ACCEPT_LANGUAGE='en')
        self.assertContains(response, 'We will reply to freuzz@test.local.')
        self.assertContains(response, 'id="contact-identity"')
        # Folded away, never removed: the reader can still answer elsewhere.
        self.assertContains(response, 'value="freuzz@test.local"')
        self.assertContains(response, 'value="Freuzz"')

    def test_an_anonymous_reader_still_gets_the_plain_fields(self):
        response = self.client.get('/contact/', HTTP_ACCEPT_LANGUAGE='en')
        self.assertNotContains(response, 'id="contact-identity"')
        self.assertNotContains(response, 'We will reply to')

    def test_an_account_with_no_address_still_gets_the_plain_fields(self):
        from django.contrib.auth.models import User
        user = User.objects.create_user('Sanmail', '', 'pw-1234')
        self.client.force_login(user)
        response = self.client.get('/contact/', HTTP_ACCEPT_LANGUAGE='en')
        self.assertNotContains(response, 'id="contact-identity"')
        self.assertNotContains(response, 'We will reply to')

    def test_the_folded_address_is_still_what_gets_mailed(self):
        from django.contrib.auth.models import User
        from django.core import mail
        user = User.objects.create_user('Freuzz', 'freuzz@test.local', 'pw-1234')
        self.client.force_login(user)
        response = self._post(email='freuzz@test.local', name='Freuzz')
        self.assertIn('thankyou', response.url)
        self.assertIn('freuzz@test.local', mail.outbox[0].body)

    def test_a_missing_name_and_address_say_so(self):
        from django.core import mail
        response = self._post(name='', email='')
        self.assertIn('thankyou', response.url)
        self.assertIn('(no name given)', mail.outbox[0].body)
        self.assertIn('(no address given)', mail.outbox[0].body)


