class LocalizedUiParityTests(SimpleTestCase):
    """The inventory, forgemagie and encyclopedia pages each carry a
    hand-maintained per-language UI dict; a key missing in one language renders
    blank there."""

    LANGS = ['en', 'fr', 'es', 'pt', 'de']

    def test_encyclopedia_ui_uses_proper_accents(self):
        from chardata.encyclopedia_view import LOCALIZED_UI
        self.assertEqual(LOCALIZED_UI['fr']['title'], 'Encyclopédie')
        self.assertEqual(LOCALIZED_UI['fr']['details_title'], "Détails de l'objet")
        self.assertEqual(LOCALIZED_UI['es']['search_label'], 'Búsqueda')
        self.assertEqual(LOCALIZED_UI['pt']['title'], 'Enciclopédia')
        self.assertEqual(LOCALIZED_UI['de']['title'], 'Enzyklopädie')

    def _assert_parity(self, dictionary, name):
        for lang in self.LANGS:
            self.assertIn(lang, dictionary, msg='%s missing %s' % (name, lang))
        base = set(dictionary['en'].keys())
        for lang in self.LANGS:
            with self.subTest(dict=name, lang=lang):
                self.assertEqual(set(dictionary[lang].keys()), base,
                                 msg='%s[%s] keys differ from en' % (name, lang))

    def test_inventory_ui_parity(self):
        from chardata.inventory_view import LOCALIZED_UI
        self._assert_parity(LOCALIZED_UI, 'inventory')

    def test_forgemagie_ui_parity(self):
        from chardata.forgemagie_view import LOCALIZED_UI, TRANSCENDENCE_UI
        self._assert_parity(LOCALIZED_UI, 'forgemagie')
        self._assert_parity(TRANSCENDENCE_UI, 'forgemagie_transcendence')

    def test_encyclopedia_ui_parity(self):
        from chardata.encyclopedia_view import LOCALIZED_UI
        self._assert_parity(LOCALIZED_UI, 'encyclopedia')

    def test_localized_ui_dicts_use_native_accents(self):
        # These three dicts are prose-heavy in every language and always carry
        # accented letters; an ASCII-transliterated block has almost none.
        # MONSTER_UI is left out: its one-word labels (Erde, Feuer, Stufe) carry
        # none of their own.
        from chardata import encyclopedia_view, forgemagie_view, inventory_view
        accented = re.compile('[À-ɏ]')
        dicts = {
            'encyclopedia.LOCALIZED_UI': encyclopedia_view.LOCALIZED_UI,
            'forgemagie.LOCALIZED_UI': forgemagie_view.LOCALIZED_UI,
            'inventory.LOCALIZED_UI': inventory_view.LOCALIZED_UI,
        }
        for name, d in dicts.items():
            for lang in ('fr', 'es', 'pt', 'de'):
                text = ' '.join(str(v) for v in d[lang].values())
                with self.subTest(dict=name, lang=lang):
                    self.assertGreaterEqual(
                        len(accented.findall(text)), 8,
                        '%s[%s] reads as ASCII-transliterated (missing native accents)'
                        % (name, lang))


class ApiDocsTests(TestCase):
    """The public API advertises /about/#api as its docs."""

    def test_about_documents_the_api(self):
        resp = self.client.get('/about/')
        self.assertContains(resp, 'id="api"')
        self.assertContains(resp, '/api/v1/shared-builds/')

    def test_about_api_section_is_translated(self):
        cases = {'fr': 'API publique', 'es': 'API p', 'pt': 'API p', 'de': 'ffentliche API'}
        for lang, needle in cases.items():
            resp = self.client.get('/about/', headers={'accept-language': lang})
            self.assertContains(resp, needle, msg_prefix=lang)

    def test_meta_endpoint_points_to_about_anchor(self):
        resp = self.client.get('/api/v1/')
        self.assertEqual(resp.json()['docs'], 'https://dofusfashionista.gg/about/#api')

    def test_api_responses_carry_cache_and_cors_headers(self):
        for url, max_age in (('/api/v1/', 'max-age=300'),
                             ('/api/v1/shared-builds/', 'max-age=60')):
            resp = self.client.get(url)
            self.assertEqual(resp.status_code, 200, url)
            self.assertEqual(resp['Access-Control-Allow-Origin'], '*', url)
            self.assertIn(max_age, resp.get('Cache-Control', ''), url)


# The Equip column counts the gear, and the exotic point the options grant is
# part of it: get_stats_gear() adds it there, not to the base.
GEAR_KINDS = ('item', 'set', 'exo')
ALL_KINDS = GEAR_KINDS + ('base', 'derived', 'cap')


class StatSourcesTests(TestCase):
    """The stats panel prints a total per stat and never said where it came
    from. Every line of the breakdown has to add up to the number printed above
    it, or the panel would be worse than saying nothing."""

    def _solved_result(self, version='dofus3'):
        from django.test import RequestFactory
        from django.contrib.auth.models import User
        from fashionistapulp.structure import set_current_game_version
        from chardata.coaching_view import create_build
        from chardata.solution import get_solution
        set_current_game_version(version)
        self.addCleanup(set_current_game_version, 'dofus3')
        owner = User.objects.create_user('sources' + version,
                                         'src-%s@test.local' % version,
                                         'pw-42-solid')
        request = RequestFactory().post('/')
        request.user = owner
        char = create_build(request, 'Iop', 200, {'str'}, version)
        self.client.force_login(owner)
        self.client.get('/fashion/%d/' % char.pk if version == 'dofus3'
                        else '/%s/fashion/%d/' % (version, char.pk))
        char.refresh_from_db()
        return char, get_solution(char)

    def _check(self, version):
        if not _pulp_solver_available():
            self.skipTest('no pulp solver available')
        from chardata.solution_result import stat_sources
        _char, result = self._solved_result(version)
        self.assertIsNotNone(result)
        sources = stat_sources(result)
        self.assertTrue(sources, 'no stat has a breakdown at all')
        total = result.get_stats_total()
        gear = result.get_stats_gear()
        for key, lines in sources.items():
            with self.subTest(version=version, stat=key):
                self.assertEqual(total.get(key, 0),
                                 sum(line['value'] for line in lines),
                                 'the lines do not make the total')
                self.assertEqual(gear.get(key, 0),
                                 sum(line['value'] for line in lines
                                     if line['kind'] in GEAR_KINDS),
                                 'the gear lines do not make the equip total')
        return result, sources

    def test_every_total_is_explained_on_dofus3(self):
        result, sources = self._check('dofus3')
        worn = {item.localized_name for item in result.item_list
                if item.item_added}
        named = {line['label'] for lines in sources.values() for line in lines
                 if line['kind'] == 'item'}
        self.assertTrue(named, 'no worn item is named anywhere')
        self.assertEqual(set(), named - worn, 'a line names something unworn')

    def test_every_total_is_explained_on_retro(self):
        self._check('retro')

    def test_a_line_carries_a_label_a_value_and_a_kind(self):
        _result, sources = self._check('dofus3')
        for lines in sources.values():
            for line in lines:
                self.assertEqual({'label', 'value', 'kind'}, set(line))
                self.assertTrue(line['label'])
                self.assertNotEqual(0, line['value'], 'a zero line says nothing')
                self.assertIn(line['kind'], ALL_KINDS)

    def test_a_half_built_result_explains_what_it_can(self):
        # The solution page must not break on a result that is missing a piece,
        # which is how the other stored-blob failures used to take a page down.
        from chardata.solution_result import stat_sources

        class HalfBuilt(object):
            def get_stats_total(self):
                return {}

        sources = stat_sources(HalfBuilt())
        self.assertIsInstance(sources, dict)
        for lines in sources.values():
            for line in lines:
                self.assertEqual({'label', 'value', 'kind'}, set(line))

    def test_what_takes_away_is_listed_under_what_gives(self):
        # Le tri portait sur abs(), donc un -15 se glissait entre un +20 et un
        # +15. Une ligne qui retire du stat se lit en bas, et le plafond d'une
        # panoplie reste apres tout le reste.
        from chardata.solution_result import stat_sources

        class Item(object):
            def __init__(self, name, stats):
                self.item_added = True
                self.localized_name = name
                self.stats = stats

        class Result(object):
            input = {'options': {'ap_exo': False, 'mp_exo': False},
                     'base_stats_by_attr': {}, 'char_level': 1}
            sets = []

            def __init__(self):
                self.item_list = [Item('Vingt', {'vit': 20}),
                                  Item('Moins quinze', {'vit': -15}),
                                  Item('Quinze', {'vit': 15}),
                                  Item('Dix', {'vit': 10})]

            def get_stats_total(self):
                return {'vit': 30}

            def get_stats_gear(self):
                return {'vit': 30}

        lines = stat_sources(Result())['vit']
        self.assertEqual([line['value'] for line in lines], [20, 15, 10, -15])

    def test_something_that_is_not_a_result_is_refused(self):
        # Handing it the wrapper instead of the result would empty the panel on
        # every build, and a quiet {} would look like a build with no gear.
        from chardata.solution_result import stat_sources

        class Bare(object):
            pass

        with self.assertRaises(TypeError):
            stat_sources(Bare())

    def test_the_panel_is_dropped_before_being_rebuilt(self):
        """Equip mode and the buff toggle rebuild the breakdown. The panel is
        appended to the stat cell itself, so it has to be removed with the
        rest: while it was not, the stale Total panel stayed on screen and
        contradicted the number beside it, and the panels piled up on every
        update."""
        import os
        page = os.path.join(os.path.dirname(__file__), 'templates', 'chardata',
                            'solution.html')
        body = io.open(page, encoding='utf-8').read()
        self.assertIn(".find('.spell-tip, .spell-tip-panel').remove()", body)

    def test_the_page_carries_the_breakdown_and_its_hooks(self):
        if not _pulp_solver_available():
            self.skipTest('no pulp solver available')
        import json
        import re
        char, _result = self._solved_result('dofus3')
        body = self.client.get('/solution/%d/' % char.pk).content.decode('utf-8')
        self.assertIn('data-stat-key="vit"', body)
        self.assertIn('STAT_SOURCES', body)
        payload = json.loads(
            re.search(r'var STAT_SOURCES = (\{.*?\});', body).group(1))
        self.assertIn('vit', payload)
        self.assertTrue(all({'label', 'value', 'kind'} == set(line)
                            for line in payload['vit']))

    def test_the_biggest_contributor_comes_first(self):
        # Par valeur signee : ce qui donne le plus en tete, ce qui retire en
        # bas. Trier sur abs() glissait un -15 entre un +20 et un +15.
        _result, sources = self._check('dofus3')
        for lines in sources.values():
            values = [line['value'] for line in lines
                      if line['kind'] != 'cap']
            self.assertEqual(sorted(values, reverse=True), values)


class RetroApMpLossTests(SimpleTestCase):
    """Three of Retro's own effect ids were read by nobody. 2100 "PA perdus" and
    127 "PM perdus" name no target, so they are the wearer's loss: Abracaska is
    +1 AP and -1 MP in the game and the site showed the AP alone, which let the
    solver spend an MP the build does not have. 101, "PA perdus a la cible", is
    the target's loss on 47 weapons, the (removes ap) line the other versions
    have always printed."""

    def test_a_hat_keeps_the_mp_it_costs(self):
        _get_equipments_retro = itemscraper_module('get_equipments_retro')
        decode_stats = _get_equipments_retro.decode_stats
        # Abracaska, the way its own ISTA line reads: 6f=+1 AP, 7f=-1 MP,
        # 7d=Vitality 21 to 35.
        stats, hits = decode_stats('6f#1##0d0+1,7f#1##0d0+1,7d#15#23#1d15+20')
        self.assertIn([1, 1, 'AP'], stats)
        self.assertIn([-1, -1, 'MP'], stats)
        self.assertEqual([], hits)

    def test_boots_keep_the_ap_they_cost(self):
        _get_equipments_retro = itemscraper_module('get_equipments_retro')
        decode_stats = _get_equipments_retro.decode_stats
        stats, _hits = decode_stats('834#1##0d0+1,f1#6#14#1d15+5')
        self.assertIn([-1, -1, 'AP'], stats)

    def test_a_weapon_takes_ap_off_the_target(self):
        _get_equipments_retro = itemscraper_module('get_equipments_retro')
        decode_stats = _get_equipments_retro.decode_stats
        # Abraton: 65 = "PA perdus a la cible", flat, plus its water hit.
        stats, hits = decode_stats('65#1##0d0+1,60#5#a#1d6+4', is_weapon=True)
        self.assertIn([1, 1, '(removes ap)'], hits)
        self.assertEqual([], stats)
        # and the rolled form of the same line
        _stats, rolled = decode_stats('65#1#2#1d2+0', is_weapon=True)
        self.assertEqual([[1, 2, '(removes ap)']], rolled)

    def test_the_built_data_carries_them(self):
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path
        conn = sqlite3.connect(get_items_db_path('retro'))
        try:
            rows = conn.execute(
                "SELECT COUNT(*) FROM weapon_hits WHERE element = 'removes_ap'"
            ).fetchone()[0]
            # A fixed stat is written with min_value and max_value NULL, the
            # amount living in value alone, so a malus is value < 0.
            maluses = conn.execute(
                'SELECT COUNT(*) FROM stats_of_item s JOIN stats t '
                'ON s.stat = t.id '
                "WHERE t.name IN ('AP', 'MP') AND s.value < 0").fetchone()[0]
        finally:
            conn.close()
        self.assertGreater(rows, 30, 'no retro weapon takes AP off its target')
        self.assertGreater(maluses, 15, 'no retro item costs AP or MP')


class RateCounterTests(TestCase):
    """The failed-login and reset-mail counts used to live in the cache, which is
    local memory here: a pool of four workers held four separate counters, so the
    real ceiling was four times the one in the code, and a reload forgot them."""

    def test_an_unknown_key_has_no_hits(self):
        from chardata.rate_limit import hits
        self.assertEqual(0, hits('nobody', 900))

    def test_hits_count_up(self):
        from chardata.rate_limit import hits, note_hit
        self.assertEqual(1, note_hit('k', 900))
        self.assertEqual(2, note_hit('k', 900))
        self.assertEqual(2, hits('k', 900))

    def test_a_count_outside_its_window_starts_again(self):
        import datetime
        from django.utils import timezone
        from chardata.models import RateCounter
        from chardata.rate_limit import hits, note_hit
        note_hit('k', 900)
        note_hit('k', 900)
        RateCounter.objects.filter(key='k').update(
            window_start=timezone.now() - datetime.timedelta(seconds=901))
        self.assertEqual(0, hits('k', 900))
        self.assertEqual(1, note_hit('k', 900))

    def test_clearing_forgets_it(self):
        from chardata.rate_limit import clear_hits, hits, note_hit
        note_hit('k', 900)
        clear_hits('k')
        self.assertEqual(0, hits('k', 900))

    def test_the_cache_no_longer_holds_the_count(self):
        from django.core.cache import cache
        from chardata.rate_limit import hits, note_hit
        note_hit('k', 900)
        note_hit('k', 900)
        cache.clear()
        self.assertEqual(2, hits('k', 900),
                         'a count that a cache flush can reset is per worker')

    def test_a_long_key_is_still_one_key(self):
        from chardata.models import RateCounter
        from chardata.rate_limit import hits, note_hit
        long_key = 'login-fail-user:' + 'x' * 400
        note_hit(long_key, 900)
        note_hit(long_key, 900)
        self.assertEqual(2, hits(long_key, 900))
        self.assertEqual(1, RateCounter.objects.count())

    def test_dead_rows_are_dropped_when_a_key_appears(self):
        import datetime
        from django.utils import timezone
        from chardata.models import RateCounter
        from chardata.rate_limit import note_hit
        RateCounter.objects.create(
            key='ancient', count=3,
            window_start=timezone.now() - datetime.timedelta(days=2))
        note_hit('brand-new', 900)
        self.assertEqual(['brand-new'],
                         list(RateCounter.objects.values_list('key', flat=True)))


class TemplateCommentsStayOutOfThePageTests(TestCase):
    """Django's {# #} comment is a one-line form. Written across two lines it is
    not a comment at all, and the text lands on the page: three of them shipped,
    one in the breadcrumb of every guide, one on the guides hub and one on the
    encyclopedia. A multi-line note has to use {% comment %}."""

    def _templates(self):
        root = os.path.join(
            os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
        for dirpath, _dirs, files in os.walk(root):
            for name in files:
                if name.endswith('.html'):
                    yield os.path.join(dirpath, name)

    def test_no_hash_comment_spans_two_lines(self):
        offenders = []
        checked = 0
        for path in self._templates():
            checked += 1
            with open(path, encoding='utf-8', errors='replace') as handle:
                for number, line in enumerate(handle, 1):
                    at = line.find('{#')
                    if at >= 0 and '#}' not in line[at:]:
                        offenders.append('%s:%d' % (os.path.basename(path),
                                                    number))
        self.assertGreater(checked, 20, 'no templates were scanned')
        self.assertEqual([], offenders,
                         'use {%% comment %%} for a note over several lines: %s'
                         % offenders)

    def test_the_pages_that_shipped_one_carry_no_template_syntax(self):
        for url in ('/guides/getting-started/', '/guides/', '/encyclopedia/'):
            body = self.client.get(url).content.decode('utf-8')
            for token in ('{#', '#}', '{%', '%}'):
                with self.subTest(url=url, token=token):
                    self.assertNotIn(token, body)


class ApiTierListRankingTests(TestCase):
    """The tier list returns the best few builds of each class. It used to read
    every shared build of the version into memory to do it, and a Char row
    carries nine pickled columns including the stored solution."""

    def setUp(self):
        from django.core.cache import cache
        cache.clear()
        self.addCleanup(cache.clear)

    def _shared(self, name, char_class, views):
        import pickle
        from django.contrib.auth.models import User
        from chardata.models import Char
        owner, _created = User.objects.get_or_create(
            username='tiersharer', defaults={'email': 'tier@test.local'})
        return Char.objects.create(
            name=name, char_name=name, char_class=char_class,
            char_build='build', level=200, minimum_stats=b'',
            minimum_crits=b'', stats_weight=b'', options=b'', inclusions=b'',
            exclusions=b'', view_count=views,
            minimal_solution=pickle.dumps({'item_per_slot': {}}), owner=owner,
            link_shared=True, game_version='dofus3')

    def _sections(self, query=''):
        body = self.client.get('/api/v1/tier-list/' + query).json()
        return {s['char_class']: s for s in body['sections']}

    def test_each_class_keeps_its_best_and_its_real_count(self):
        for i, views in enumerate((1, 40, 7, 3)):
            self._shared('Iop%d' % i, 'Iop', views)
        for i, views in enumerate((5, 2)):
            self._shared('Cra%d' % i, 'Cra', views)
        sections = self._sections('?top=2')
        self.assertEqual(4, sections['Iop']['count'])
        self.assertEqual(2, sections['Cra']['count'])
        self.assertEqual(['Iop1', 'Iop2'],
                         [b['name'] for b in sections['Iop']['top']])
        self.assertEqual(['Cra0', 'Cra1'],
                         [b['name'] for b in sections['Cra']['top']])

    def test_it_builds_no_payload_for_a_build_it_will_not_return(self):
        from unittest import mock
        from chardata import api_view
        for i in range(6):
            self._shared('Iop%d' % i, 'Iop', i)
        for i in range(4):
            self._shared('Cra%d' % i, 'Cra', i)
        real = api_view._build_payload
        with mock.patch.object(api_view, '_build_payload',
                               side_effect=real) as spy:
            sections = self._sections('?top=1')
        self.assertEqual(2, spy.call_count, 'ten builds, two returned')
        self.assertEqual(6, sections['Iop']['count'])
        self.assertEqual(4, sections['Cra']['count'])

    def test_the_creator_name_costs_no_query_per_row(self):
        for i in range(6):
            self._shared('Iop%d' % i, 'Iop', i)
        # One count query, one ranked read, one alias lookup. The owner name has
        # to ride along with the row, not come back for it.
        with self.assertNumQueries(3):
            sections = self._sections('?top=3')
        self.assertEqual(3, len(sections['Iop']['top']))
        self.assertTrue(all(b['creator'] for b in sections['Iop']['top']))

    def test_a_class_with_fewer_builds_than_asked_still_answers(self):
        self._shared('OnlyOne', 'Sram', 3)
        sections = self._sections('?top=5')
        self.assertEqual(1, sections['Sram']['count'])
        self.assertEqual(['OnlyOne'], [b['name'] for b in sections['Sram']['top']])

    def test_the_view_part_of_the_score_stays_capped(self):
        self._shared('Modest', 'Eniripsa', 50)
        self._shared('Viral', 'Eniripsa', 5000)
        top = self._sections('?top=2')['Eniripsa']['top']
        self.assertEqual({50}, {b['score'] for b in top})


class ApiListsOnlyOpenableBuildsTests(TestCase):
    """The api hands out an id a consumer turns into a /s/ url. A build whose
    solution was never stored has no such page: the gallery and the sitemap
    both skip it, and the api used to list it."""

    def setUp(self):
        # The api answers are cache_page'd, and the cache outlives a test: any
        # earlier test that touched these urls would serve its answer to this
        # one. That is exactly how these two tests passed alone and failed in
        # the suite.
        from django.core.cache import cache
        cache.clear()
        self.addCleanup(cache.clear)

    def _shared(self, name, blob):
        from django.contrib.auth.models import User
        from chardata.models import Char
        owner, _created = User.objects.get_or_create(
            username='apisharer', defaults={'email': 'api@test.local'})
        return Char.objects.create(
            name=name, char_name=name, char_class='Iop', char_build='build',
            level=200, minimum_stats=b'', minimum_crits=b'', stats_weight=b'',
            options=b'', inclusions=b'', exclusions=b'',
            minimal_solution=blob, owner=owner, link_shared=True,
            game_version='dofus3')

    def test_a_build_with_no_solution_is_not_listed(self):
        import pickle
        self._shared('ApiAvecSolution', pickle.dumps({'item_per_slot': {}}))
        self._shared('ApiSansSolution', b'')
        names = [row['name'] for row
                 in self.client.get('/api/v1/shared-builds/').json()['results']]
        self.assertIn('ApiAvecSolution', names)
        self.assertNotIn('ApiSansSolution', names)

    def test_the_tier_list_skips_it_too(self):
        import pickle
        self._shared('ApiAvecSolution', pickle.dumps({'item_per_slot': {}}))
        self._shared('ApiSansSolution', b'')
        body = self.client.get('/api/v1/tier-list/').content.decode('utf-8')
        self.assertNotIn('ApiSansSolution', body)

    def test_the_payload_carries_no_private_field(self):
        import pickle
        self._shared('ApiAvecSolution', pickle.dumps({'item_per_slot': {}}))
        rows = self.client.get('/api/v1/shared-builds/').json()['results']
        self.assertTrue(rows)
        for row in rows:
            with self.subTest(row=row.get('name')):
                self.assertNotIn('email', row)
                self.assertNotIn('owner_id', row)
                # the raw primary key never leaves, only the encoded id
                self.assertNotIsInstance(row['id'], int)


class CommentNotificationLanguageTests(TestCase):
    """The build owner gets the new-comment email in the language they last
    picked in the language selector."""

    def _make_build(self, owner):
        from chardata.models import Char
        return Char.objects.create(
            name='Mail build', char_name='hero', char_class='Iop',
            char_build='build', level=200,
            minimum_stats=b'', minimum_crits=b'', stats_weight=b'',
            options=b'', inclusions=b'', exclusions=b'',
            owner=owner, link_shared=True, game_version='dofus3')

    def test_setlang_remembers_the_choice(self):
        from django.contrib.auth.models import User
        from chardata.models import UserAlias
        user = User.objects.create_user('polyglot', 'p@test.local', 'pw-42-solid')
        self.client.force_login(user)
        resp = self.client.post('/i18n/setlang/', {'language': 'de'})
        self.assertIn(resp.status_code, (200, 302))
        self.assertEqual(UserAlias.objects.get(user=user).language, 'de')

    def test_login_backfills_language(self):
        from django.contrib.auth.models import User
        from chardata.models import UserAlias
        user = User.objects.create_user('nolang', 'n@test.local', 'pw-42-solid')
        with translation.override('pt'):
            self.client.force_login(user)
        self.assertEqual(UserAlias.objects.get(user=user).language, 'pt')

    def test_login_does_not_overwrite_explicit_choice(self):
        from django.contrib.auth.models import User
        from chardata.models import UserAlias
        user = User.objects.create_user('haslang', 'h@test.local', 'pw-42-solid')
        UserAlias.objects.create(user=user, language='de')
        with translation.override('fr'):
            self.client.force_login(user)
        self.assertEqual(UserAlias.objects.get(user=user).language, 'de')

    def test_account_page_saves_email_language(self):
        from django.contrib.auth.models import User
        from chardata.models import UserAlias
        user = User.objects.create_user('settings-user', 's@test.local', 'pw-42-solid')
        self.client.force_login(user)
        resp = self.client.get('/manageaccount/')
        self.assertContains(resp, 'email_language')
        resp = self.client.post('/saveaccount/', {'alias': 'Testeur', 'email_language': 'es'})
        self.assertEqual(resp.status_code, 200)
        self.assertEqual(resp.json()['email_language'], 'es')
        self.assertEqual(UserAlias.objects.get(user=user).language, 'es')
        self.client.post('/saveaccount/', {'alias': 'Testeur', 'email_language': 'xx'})
        self.assertEqual(UserAlias.objects.get(user=user).language, 'es')
        self.client.post('/saveaccount/', {'alias': 'Testeur'})
        self.assertEqual(UserAlias.objects.get(user=user).language, 'es')
        # The empty value is the "Automatic" option.
        self.client.post('/saveaccount/', {'alias': 'Testeur', 'email_language': ''})
        self.assertIsNone(UserAlias.objects.get(user=user).language)

    def test_notification_email_uses_owner_language(self):
        from django.contrib.auth.models import User
        from django.core import mail
        from chardata.models import UserAlias
        owner = User.objects.create_user('owner-fr', 'owner@test.local', 'pw-42-solid')
        UserAlias.objects.create(user=owner, language='fr')
        build = self._make_build(owner)
        commenter = User.objects.create_user('lecteur', 'l@test.local', 'pw-42-solid')
        self.client.force_login(commenter)
        resp = self.client.post('/postcomment/%d/' % build.id,
                                {'content': 'Tres joli build, bravo pour le travail.'})
        self.assertEqual(resp.status_code, 200)
        self.assertEqual(len(mail.outbox), 1)
        msg = mail.outbox[0]
        self.assertIn('Nouveau commentaire sur ton build', msg.subject)
        self.assertIn('vient de commenter', msg.body)
        html = msg.alternatives[0][0]
        self.assertIn('lang="fr"', html)


class WizardSlidersRoundTripTests(SimpleTestCase):
    """The tuning page maps sliders to solver weights and back."""

    def test_set_then_get_round_trips_for_every_slider(self):
        import collections
        from chardata.wizard_sliders import (SLIDER_RANGES,
                                             get_slider_value_from_weights,
                                             set_weights_from_slider_value)
        weights = collections.defaultdict(int)
        for key, (low, high) in SLIDER_RANGES.items():
            for value in (low, (low + high) // 2, high):
                set_weights_from_slider_value(key, value, weights)
                got = get_slider_value_from_weights(key, weights)
                self.assertEqual(got, value,
                                 'slider %r: set %s, got back %s' % (key, value, got))


class CheckPagesCommandTests(TestCase):
    """check_pages walks every public route on every version and language, with
    the query strings a crawler invents, and fails on anything that answers 500.
    Every production 500 this project has had was found by a player or by the
    error mailbox; this one is meant to find them first."""

    def test_it_walks_the_public_pages_without_a_500(self):
        from io import StringIO
        from django.core.management import call_command
        out = StringIO()
        # Seme quelques temoins : sans personnages en base la commande ne
        # visite que les pages statiques -- 53 pages au lieu de 629 le meme
        # jour -- et rend exactement le meme "aucun 500". La profondeur du
        # balayage etait une variable silencieuse jusqu'a ce qu'elle soit dite.
        call_command('check_pages', only='retro', languages='fr,de', seed=6,
                     stdout=out)
        printed = out.getvalue()
        self.assertIn('no page answered 500', printed)
        self.assertIn('6 character(s) in the database', printed)
        walked = int(printed.split('pages walked:')[1].split()[0])
        self.assertGreater(walked, 30, printed)
        # and it follows what those pages link to
        followed = int(printed.split('internal links followed:')[1].split()[0])
        self.assertGreater(followed, 20, printed)

    def test_an_empty_database_is_reported_as_a_shallow_walk(self):
        """A green obtained on 53 pages reads the same as one on 629.

        The depth used to depend on whatever a throwaway file outside the
        repository happened to hold: ninety characters made the walk cover
        the build and solution pages, none made it skip them, and both
        printed "no page answered 500".
        """
        from io import StringIO
        from django.core.management import call_command
        out = StringIO()
        with self.assertRaises(SystemExit):
            call_command('check_pages', only='retro', languages='fr',
                         stdout=out)
        printed = out.getvalue()
        self.assertIn('SHALLOW', printed)
        self.assertIn('0 character(s) in the database', printed)
        # Et il ne doit pas se taire sur ce qu il a quand meme couvert.
        self.assertIn('pages walked:', printed)

    def test_it_fails_when_a_page_breaks(self):
        from io import StringIO
        from unittest import mock
        from django.core.management import call_command
        with mock.patch('django.test.Client.get',
                        side_effect=ValueError('deliberate break')):
            with self.assertRaises(SystemExit):
                call_command('check_pages', only='retro', languages='fr',
                             stdout=StringIO())

    def test_an_unusable_database_is_named_as_such(self):
        # Run with settings_test outside the test runner and the char table does
        # not exist, which used to be reported as fifteen broken pages.
        from io import StringIO
        from unittest import mock
        from django.core.management import call_command, CommandError
        from django.db.utils import OperationalError
        with mock.patch('chardata.models.Char.objects.exists',
                        side_effect=OperationalError('no such table')):
            with self.assertRaises(CommandError) as caught:
                call_command('check_pages', only='retro', languages='fr',
                             stdout=StringIO())
        self.assertIn('settings_dev', str(caught.exception))


class UnreadableCharBlobTests(TestCase):
    """A Char keeps eight pickled columns of objects that have been renamed and
    moved over the years. One that no longer reads back used to raise out of
    whatever page touched it: a single shared build with an unreadable
    minimum_stats answered 500 for every visitor of the public gallery, not
    just for itself."""

    COLUMNS = ('minimum_stats', 'stats_weight', 'options', 'inclusions',
               'exclusions', 'aspects', 'empty_slots', 'stat_overrides')

    def _solved_shared_build(self, name):
        from django.test import RequestFactory
        from django.contrib.auth.models import User
        from chardata.coaching_view import create_build
        owner = User.objects.create_user(name.lower(), '%s@t.local' % name.lower(),
                                         'pw-42-solid')
        request = RequestFactory().post('/')
        request.user = owner
        char = create_build(request, 'Iop', 50, {'str'}, 'dofus3')
        char.name = char.char_name = name
        char.save()
        self.client.force_login(owner)
        self.client.get('/fashion/%d/' % char.pk)
        char.refresh_from_db()
        char.link_shared = True
        char.save()
        self.client.logout()
        return char

    def test_no_single_unreadable_column_takes_a_page_down(self):
        if not _pulp_solver_available():
            self.skipTest('no pulp solver available')
        from chardata.solution_view import shared_build_path
        for column in self.COLUMNS:
            char = self._solved_shared_build('Sonde' + column.replace('_', ''))
            setattr(char, column, b'not-a-pickle')
            char.save()
            with self.subTest(column=column):
                self.assertEqual(200, self.client.get('/sharedbuilds/').status_code)
                self.assertEqual(200,
                                 self.client.get(shared_build_path(char)).status_code)

    def test_no_column_is_unpickled_bare(self):
        """Every pickle.loads of a stored column goes through the helper or a
        try. One that does neither is a 500 waiting for the day that column
        stops reading back."""
        import ast
        import glob
        chardata_dir = os.path.dirname(os.path.abspath(__file__))
        offenders = []
        for path in glob.glob(os.path.join(chardata_dir, '*.py')):
            name = os.path.basename(path)
            if name in ('tests.py', 'char_blobs.py'):
                continue
            with open(path, encoding='utf-8') as handle:
                tree = ast.parse(handle.read(), filename=name)
            guarded = set()
            for node in ast.walk(tree):
                if isinstance(node, ast.Try):
                    for child in ast.walk(node):
                        guarded.add(id(child))
            for node in ast.walk(tree):
                if not isinstance(node, ast.Call):
                    continue
                func = node.func
                if not (isinstance(func, ast.Attribute) and func.attr == 'loads'
                        and isinstance(func.value, ast.Name)
                        and func.value.id == 'pickle'):
                    continue
                if not node.args or not isinstance(node.args[0], ast.Attribute):
                    continue
                if id(node) not in guarded:
                    offenders.append('%s:%d' % (name, node.lineno))
        self.assertEqual([], offenders,
                         'a stored column is unpickled with nothing to catch it')

    def test_a_reader_falls_back_to_the_empty_value(self):
        from chardata.char_blobs import read_char_blob
        self.assertEqual({}, read_char_blob(b'not-a-pickle', {}, 'minimum_stats'))
        self.assertEqual([], read_char_blob(b'not-a-pickle', [], 'exclusions'))
        self.assertEqual({}, read_char_blob(b'', {}, 'options'))
        self.assertEqual({'ap': 12}, read_char_blob(
            __import__('pickle').dumps({'ap': 12}), {}, 'minimum_stats'))


class SharedBuildsHideInvalidTests(TestCase):
    """What the gallery offers has to open. A build whose stored solution
    cannot be read has no page at all: its /s/ url raised straight out of
    pickle, a 500 on a public link nobody could fix. The reader's "hide invalid
    or outdated" checkbox is a different thing, it hides builds that render
    fine but no longer respect a condition."""

    def _make_build(self, name, blob):
        from django.contrib.auth.models import User
        from chardata.models import Char
        owner, _created = User.objects.get_or_create(
            username='sharer', defaults={'email': 'sh@test.local'})
        return Char.objects.create(
            name=name, char_name=name, char_class='Iop',
            char_build='build', level=200,
            minimum_stats=b'', minimum_crits=b'', stats_weight=b'',
            options=b'', inclusions=b'', exclusions=b'',
            minimal_solution=blob,
            owner=owner, link_shared=True, game_version='dofus3')

    def _solved_shared_build(self, name):
        """A real solved build: nothing short of one renders a /s/ page."""
        from django.test import RequestFactory
        from django.contrib.auth.models import User
        from chardata.coaching_view import create_build
        owner = User.objects.create_user(name.lower(), '%s@t.local' % name.lower(),
                                         'pw-42-solid')
        request = RequestFactory().post('/')
        request.user = owner
        char = create_build(request, 'Iop', 50, {'str'}, 'dofus3')
        char.name = name
        char.char_name = name
        char.save()
        self.client.force_login(owner)
        self.client.get('/fashion/%d/' % char.pk)
        char.refresh_from_db()
        char.link_shared = True
        char.save()
        self.client.logout()
        return char

    def test_a_build_with_no_readable_solution_is_never_listed(self):
        self._make_build('SansSolutionDuTout', b'')
        self._make_build('CorrompuDansLaListe', b'not-a-pickle')
        for query in ('', '?hide_invalid=1'):
            with self.subTest(query=query):
                body = self.client.get('/sharedbuilds/' + query)
                self.assertNotContains(body, 'SansSolutionDuTout')
                self.assertNotContains(body, 'CorrompuDansLaListe')

    def test_a_corrupt_build_answers_404_not_500(self):
        # pickle.loads used to raise straight out of the public page.
        from chardata.solution_view import shared_build_path
        char = self._make_build('CorrompuPublic', b'not-a-pickle')
        self.assertEqual(404, self.client.get(shared_build_path(char)).status_code)

    def test_every_build_the_list_links_to_opens(self):
        import re
        if not _pulp_solver_available():
            self.skipTest('no pulp solver available')
        self._solved_shared_build('StuffQuiSOuvre')
        self._make_build('SansSolutionDuTout', b'')
        self._make_build('CorrompuDansLaListe', b'not-a-pickle')
        body = self.client.get('/sharedbuilds/').content.decode('utf-8')
        self.assertIn('StuffQuiSOuvre', body)
        paths = set(re.findall(r'href="([^"]*/s/[^"]+)"', body))
        self.assertTrue(paths, 'the list shows no shared build at all')
        for path in paths:
            if not path.startswith('/'):
                path = '/' + path.split('/', 3)[-1]
            with self.subTest(path=path):
                self.assertEqual(200, self.client.get(path).status_code)


class SharedBuildMetaVersionTests(TestCase):
    """Shared-build cards must score and preview items from the build's own
    game version, even when called outside a versioned request."""

    @staticmethod
    def _base_input():
        return {
            'options': {'ap_exo': False, 'mp_exo': False},
            'origin': 'generated',
            'char_level': 200,
            'base_stats_by_attr': {
                'Vitality': 0,
                'Wisdom': 0,
                'Strength': 0,
                'Intelligence': 0,
                'Chance': 0,
                'Agility': 0,
            },
            'locked_equips': {},
        }

    def test_meta_uses_build_game_version_for_preview_and_public_score(self):
        import pickle as _pickle
        from django.contrib.auth.models import User
        from django.core.cache import cache
        from chardata.image_store import get_image_url
        from chardata.models import Char
        from chardata.shared_builds_view import _get_shared_build_meta
        from fashionistapulp.modelresult import ModelResultMinimal
        from fashionistapulp.structure import (get_current_game_version,
                                               get_structure,
                                               set_current_game_version)
        from static_s3.templatetags.static_s3 import static

        cache.clear()
        retro = get_structure('retro')
        modern = get_structure('dofus3')
        retro_hat = None
        for candidate in retro.get_unique_items_by_type_and_level('Hat', 200):
            modern_item = modern.get_item_by_id(candidate.id)
            has_public_score = any(
                value > 0 and retro.get_stat_by_id(stat_id) is not None
                for stat_id, value in candidate.stats)
            if (not candidate.removed and candidate.ankama_id and has_public_score
                    and (modern_item is None or modern_item.name != candidate.name)):
                retro_hat = candidate
                break
        self.assertIsNotNone(retro_hat, 'no distinct Retro hat found')

        owner = User.objects.create_user('retrometa', 'retrometa@test.local',
                                         'pw-42-solid')
        char = Char.objects.create(
            name='RetroMeta', char_name='retrometa', char_class='Iop',
            char_build='build', level=200,
            minimum_stats=b'', minimum_crits=b'', stats_weight=b'',
            options=b'', inclusions=b'', exclusions=b'',
            minimal_solution=_pickle.dumps(ModelResultMinimal(
                {'hat': retro_hat.id}, self._base_input(), {})),
            owner=owner, link_shared=True, game_version='retro')

        previous_version = get_current_game_version()
        set_current_game_version('dofus3')
        self.addCleanup(set_current_game_version, previous_version)
        with translation.override('en'):
            meta = _get_shared_build_meta(char)

        self.assertFalse(meta['has_missing_items'])
        self.assertFalse(meta['has_outdated_slots'])
        self.assertGreater(meta['public_score'], 0)
        self.assertEqual(len(meta['preview_items']), 1)
        self.assertEqual(meta['preview_items'][0]['name'],
                         retro.get_item_name_in_language(retro_hat, 'en'))
        expected_image_url = static(get_image_url(
            retro.get_type_name_by_id(retro_hat.type), retro_hat.name, 'retro'))
        self.assertEqual(meta['preview_items'][0]['image_url'], expected_image_url)
        self.assertEqual(get_current_game_version(), 'dofus3')


