class TouchPetSolveTests(TestCase):
    """Touch ships maxed pet variants as synthesized items. Mounts are all level
    60, so at level 50 the Pet slot can only hold one of those variants."""

    VARIANT_ID_BASE = 200000000

    def test_touch_structure_has_maxed_pet_variants(self):
        from fashionistapulp.structure import get_structure
        st = get_structure('touch')
        variant = st.get_item_by_name('Bow Meow (+110 Strength)')
        self.assertIsNotNone(variant,
                             'maxed touch pet variants missing from items_touch.db')
        self.assertGreaterEqual(variant.id, self.VARIANT_ID_BASE)
        self.assertEqual(st.get_type_name_by_id(variant.type), 'Pet')

    @unittest.skipUnless(_pulp_solver_available(), 'no pulp solver available')
    def test_touch_strength_solve_equips_a_maxed_pet_variant(self):
        from django.test import RequestFactory
        from django.contrib.auth.models import User
        from fashionistapulp.structure import set_current_game_version
        from chardata.coaching_view import create_build
        from chardata.solution import get_solution
        set_current_game_version('touch')
        self.addCleanup(set_current_game_version, 'dofus3')
        owner = User.objects.create_user('touchsolve', 'ts@test.local', 'pw-42-solid')
        req = RequestFactory().post('/')
        req.user = owner
        # The real creation path seeds the default exclusions (GM pets...).
        char = create_build(req, 'Iop', 50, {'str'}, 'touch')
        self.client.force_login(owner)
        resp = self.client.get('/touch/fashion/%d/' % char.pk)
        self.assertIn(resp.status_code, (200, 302))
        char.refresh_from_db()
        solution = get_solution(char)
        self.assertIsNotNone(solution, 'no solution stored after solving')
        pet = next((ri for ri in solution.item_list
                    if ri.item_added and ri.type == 'Pet'), None)
        self.assertIsNotNone(pet, 'no pet equipped on a touch strength solve')
        self.assertGreaterEqual(
            pet.id, self.VARIANT_ID_BASE,
            'expected a maxed pet variant in the Pet slot, got %r' % pet.name)


class TouchPetBonusFileTests(SimpleTestCase):
    """The variants are written back into the items table as pets, carrying the
    pet's own ankama id, and they are numbered in file order. So a scrape that
    reads them as pets writes its own output back into the file, and any pet
    that falls out of the file renumbers every pet after it: the day Moowitty
    went missing, 82 saved builds pointed at another player's pet."""

    VARIANT_ID_BASE = 200000000

    def _bonuses(self):
        import json
        repo_root = os.path.dirname(
            os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
        path = os.path.join(repo_root, 'itemscraper', 'touch_pet_bonuses.json')
        with open(path, encoding='utf-8') as handle:
            return json.load(handle)

    def test_the_file_names_pets_and_never_its_own_variants(self):
        fed_back = sorted(name for name in self._bonuses() if '(+' in name)
        self.assertEqual([], fed_back[:5],
                         '%d generated variant(s) were scraped back in as pets'
                         % len(fed_back))

    def test_every_pet_named_is_a_touch_pet_the_solver_knows(self):
        from fashionistapulp.structure import get_structure
        structure = get_structure('touch')
        unknown, wrong_slot, generated = [], [], []
        for name in self._bonuses():
            item = structure.get_item_by_name(name)
            if item is None:
                unknown.append(name)
            elif structure.get_type_name_by_id(item.type) != 'Pet':
                wrong_slot.append(name)
            elif item.id >= self.VARIANT_ID_BASE:
                generated.append(name)
        self.assertEqual(([], [], []), (unknown, wrong_slot, generated))

    def test_every_bonus_of_the_file_reached_the_solver(self):
        # A bonus becomes a variant unless the pet already carries that exact
        # value as a datacenter stat, in which case a variant would be a copy.
        from fashionistapulp.structure import get_structure
        structure = get_structure('touch')
        variant_stats = {}
        for item in structure.get_items_list():
            if item.id >= self.VARIANT_ID_BASE and ' (' in item.name:
                base = item.name.rsplit(' (', 1)[0]
                variant_stats.setdefault(base, set()).update(item.stats or [])

        missing = []
        for name, bonuses in self._bonuses().items():
            pet = structure.get_item_by_name(name)
            if pet is None:
                continue  # the test above is the one that reports this
            carried = set(pet.stats or []) | variant_stats.get(name, set())
            for stat_name, value in bonuses:
                stat = structure.get_stat_by_name(stat_name)
                if stat is not None and (stat.id, int(value)) not in carried:
                    missing.append((name, stat_name, value))
        self.assertEqual([], missing,
                         '%d bonus line(s) of the file reach no item' % len(missing))


class FedPetPageTests(TestCase):
    """A Touch or Retro pet carries no bonus in the data: it is fed up to a cap.
    The page used to print "Characteristics -" and stop there, while the tool
    itself knew the pet reaches 110 Agility. Retro said so, Touch did not."""

    # Air Bwak, the same ankama id on both, fed toward three different stats.
    PET_ANKAMA_ID = 2076

    def _sections(self, version, language='en'):
        import re
        prefix = '' if version == 'dofus3' else '/' + version
        response = self.client.get(
            '%s/encyclopedia/item/equipment/%d-x/' % (prefix, self.PET_ANKAMA_ID),
            headers={'accept-language': language})
        self.assertEqual(200, response.status_code, version)
        return re.findall(r'<b>([^<]+)</b>', response.content.decode('utf-8'))

    def test_touch_and_retro_say_what_the_pet_reaches(self):
        from chardata.encyclopedia_view import _ui_text
        for version in ('touch', 'retro'):
            with self.subTest(version=version):
                sections = self._sections(version)
                self.assertIn(_ui_text()['pet_feedable_label'], sections)
                # and no empty characteristics block above it
                self.assertNotIn(_ui_text()['stats_label'], sections)

    def test_a_modern_pet_keeps_its_plain_characteristics(self):
        from chardata.encyclopedia_view import _ui_text
        sections = self._sections('dofus3')
        self.assertIn(_ui_text()['stats_label'], sections)
        self.assertNotIn(_ui_text()['pet_feedable_label'], sections)

    def test_the_label_is_translated_everywhere(self):
        for language in ('en', 'fr', 'es', 'pt', 'de'):
            with self.subTest(language=language):
                sections = self._sections('touch', language)
                self.assertTrue(
                    any('fed' in s.lower() or 'nourr' in s.lower()
                        or 'comida' in s.lower() or 'aliment' in s.lower()
                        or 'fütterung' in s.lower() for s in sections),
                    'no feeding section in %s: %s' % (language, sections[:5]))


class RetroPetBonusFileTests(SimpleTestCase):
    """Retro feeds its pets too, and numbers its variants the same way, from a
    counter over the file. Its scrape reads two fan sites and keeps a blank
    entry for every feedable pet, so a source going quiet does not remove a
    pet: it empties one, which loses that pet's variants and renumbers the
    rest all the same."""

    VARIANT_ID_BASE = 10000000

    def _bonuses(self):
        import json
        repo_root = os.path.dirname(
            os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
        path = os.path.join(repo_root, 'itemscraper', 'retro_pet_bonuses.json')
        with open(path, encoding='utf-8') as handle:
            return json.load(handle)

    def test_the_file_names_pets_and_never_its_own_variants(self):
        fed_back = sorted(name for name in self._bonuses() if '(+' in name)
        self.assertEqual([], fed_back[:5])

    def test_every_bonus_of_the_file_reached_the_solver(self):
        from fashionistapulp.structure import get_structure
        structure = get_structure('retro')
        variant_stats = {}
        for item in structure.get_items_list():
            if item.id >= self.VARIANT_ID_BASE and ' (' in item.name:
                base = item.name.rsplit(' (', 1)[0]
                variant_stats.setdefault(base, set()).update(item.stats or [])

        missing = []
        for name, bonuses in self._bonuses().items():
            pet = structure.get_item_by_name(name)
            if pet is None or not bonuses:
                continue  # a blank entry is the checklist saying "no source"
            carried = set(pet.stats or []) | variant_stats.get(name, set())
            for stat_name, value in bonuses:
                stat = structure.get_stat_by_name(stat_name)
                if stat is not None and (stat.id, int(value)) not in carried:
                    missing.append((name, stat_name, value))
        self.assertEqual([], missing,
                         '%d bonus line(s) of the file reach no item' % len(missing))

    def test_a_pet_that_lost_its_bonuses_stops_the_scrape(self):
        # The guard that fires before the file is written. Reading the source
        # rather than running it: the scrape needs two live fan sites.
        repo_root = os.path.dirname(
            os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
        for name in ('scrape_retro_pet_bonuses.py', 'scrape_touch_pet_bonuses.py'):
            path = os.path.join(repo_root, 'itemscraper', name)
            with open(path, encoding='utf-8') as handle:
                source = handle.read()
            with self.subTest(scraper=name):
                self.assertIn('allow-shrink', source)
                self.assertIn('nothing written', source)


class OldBuildsKeepTheirItemsTests(SimpleTestCase):
    """Collapsing the "(#1)"/"(#2)" rows into one item retires ids that saved
    builds store, and a build whose id no longer resolves loses that slot in
    silence. legacy_item_ids carries the retired rows onto the item they became,
    and the synthesized Gelano rows stop moving with the data."""

    VERSIONS = ('dofus3', 'beta', 'dofus2', 'touch', 'retro')

    def test_no_version_still_ships_a_split_row(self):
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path
        for version in self.VERSIONS:
            path = get_items_db_path(version)
            if not os.path.exists(path):
                continue
            connection = sqlite3.connect('file:%s?mode=ro' % path, uri=True)
            try:
                left = connection.execute(
                    "SELECT COUNT(*) FROM items WHERE name LIKE '%(#%'").fetchone()[0]
            finally:
                connection.close()
            with self.subTest(version=version):
                self.assertEqual(left, 0)

    def test_a_retired_row_still_finds_its_item(self):
        from fashionistapulp.structure import get_structure, set_current_game_version
        self.addCleanup(set_current_game_version, 'dofus3')
        for version in ('dofus3', 'beta'):
            set_current_game_version(version)
            structure = get_structure(version)
            self.assertTrue(structure.legacy_item_ids,
                            'no retired ids recorded for %s' % version)
            for old_id, item_id in structure.legacy_item_ids.items():
                with self.subTest(version=version, old_id=old_id):
                    found = structure.get_item_by_id(old_id)
                    self.assertIsNotNone(
                        found, 'a build storing %d loses that slot' % old_id)
                    self.assertEqual(found.id, item_id)

    def test_the_gelano_rows_have_a_fixed_id(self):
        from fashionistapulp.structure import (get_structure, set_current_game_version,
                                               GELANO_IDS, GELANO_DEPLOYED_IDS)
        self.addCleanup(set_current_game_version, 'dofus3')
        for version in self.VERSIONS:
            set_current_game_version(version)
            structure = get_structure(version)
            gelano = structure.items_dict_name.get('Gelano (#1)')
            with self.subTest(version=version):
                self.assertIsNotNone(gelano)
                self.assertEqual(gelano.id, GELANO_IDS['Gelano (#1)'])
                for old_id in GELANO_DEPLOYED_IDS.get(version, {}):
                    # A retired id that some item now uses is worse than a
                    # missing one: the alias is silent and the item wins.
                    self.assertNotIn(
                        old_id, structure.items_dict,
                        'a retired Gelano id is a live item on %s' % version)
                    found = structure.get_item_by_id(old_id)
                    self.assertIsNotNone(found)
                    self.assertEqual(found.name, 'Gelano (#1)')


class OneItemCountsOnceTests(TestCase):
    """An item gated behind alternative conditions ships as "(#1)" and "(#2)",
    and the exo variants do the same. The group was used to forbid and to lock,
    never to count, so both rows of Crocoring could fill the two ring slots: one
    ring worn twice, and two pieces of its set counted from one. A setless ring
    is the pair the game does allow, so that one has to stay."""

    OPTIONS = {'ap_exo': False, 'range_exo': False, 'mp_exo': False,
               'dofus': True, 'dragoturkey': True, 'seemyool': True,
               'rhineetle': True, 'prysmaradite': False, 'shields': True,
               'trophies': True}

    def _solve(self, locked):
        from fashionistapulp.model import Model, ModelInput
        from fashionistapulp.dofus_constants import STAT_NAME_TO_KEY
        weights = {key: 0 for key in STAT_NAME_TO_KEY.values()}
        weights.update({'vit': 40, 'pow': 60})
        model_input = ModelInput(
            char_level=200,
            base_stats_by_attr={'Vitality': 0, 'Wisdom': 0, 'Strength': 0,
                                'Intelligence': 0, 'Chance': 0, 'Agility': 0},
            minimum_stats={}, locked_equips=locked, forbidden_equips=set(),
            objective_values=weights, options=self.OPTIONS, char_class='Iop',
            stat_points_to_distribute=5 * 199)
        model = Model()
        model.setup(model_input)
        model.run(2)
        return model.get_solved_status()

    def test_every_split_group_is_counted_as_one_item(self):
        from fashionistapulp.structure import get_structure, set_current_game_version
        from fashionistapulp.model import Model
        for version in ('dofus3', 'beta', 'dofus2', 'touch', 'retro'):
            self.addCleanup(set_current_game_version, 'dofus3')
            set_current_game_version(version)
            structure = get_structure(version)
            groups = {name: members for name, members
                      in structure.get_available_or_items().items()
                      if len(members) > 1}
            if not groups:
                continue
            model = Model()
            with self.subTest(version=version):
                for name, members in groups.items():
                    self.assertIn(members[0].id,
                                  model.restrictions.or_item_count_constraints,
                                  '%s is not counted as one item' % name)

    def test_a_set_ring_cannot_fill_both_ring_slots(self):
        # It used to reach both slots through its two condition rows. There is
        # one row now, and the solver may take a set ring only once, so the two
        # ring slots can no longer both hold it.
        from fashionistapulp.structure import get_structure, set_current_game_version
        from fashionistapulp.model import Model
        self.addCleanup(set_current_game_version, 'dofus3')
        set_current_game_version('dofus3')
        structure = get_structure('dofus3')
        crocoring = structure.get_item_by_name('Crocoring')
        self.assertIsNotNone(crocoring)
        self.assertIsNotNone(crocoring.set, 'Crocoring stopped being a set ring')
        rows = [item for item in structure.items_dict.values()
                if item.ankama_id == crocoring.ankama_id]
        self.assertEqual(len(rows), 1, 'Crocoring is split again: %s'
                         % [item.name for item in rows])
        model = Model()
        self.assertEqual(
            model.problem.pulp_vars['x_%d' % crocoring.id].upBound, 1)

    @unittest.skipUnless(_pulp_solver_available(), 'no pulp solver available')
    def test_a_setless_ring_still_fills_both_ring_slots(self):
        from fashionistapulp.structure import get_structure, set_current_game_version
        self.addCleanup(set_current_game_version, 'dofus3')
        set_current_game_version('dofus3')
        structure = get_structure('dofus3')
        band = structure.get_item_by_name('Awmigawd Band')
        self.assertIsNotNone(band)
        self.assertIsNone(band.set, 'Awmigawd Band gained a set')
        locked = {'ring1': band.id, 'ring2': band.id}
        self.assertEqual(self._solve(locked), 'Optimal')


class OrEquipConditionTests(TestCase):
    """Touch gates some items on either of two stats, "MP < 6 or AP < 12" on the
    Professor Xa set. Keeping both as AND rows would forbid builds the game
    allows, so the condition used to be dropped whole and the item went out
    unconstrained: a player asked the wizard for 12 AP and got pieces capped at
    11. The solver picks one branch per worn item now."""

    KNOWN = {
        'Professor Xa\'s Cloak': [('MP', True, 5), ('AP', True, 11)],
        'Flinty Daggers': [('Strength', False, 451), ('Agility', False, 451)],
    }

    def test_the_scraper_keeps_the_disjunction(self):
        import importlib.util
        repo_root = os.path.dirname(
            os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
        path = os.path.join(repo_root, 'itemscraper', 'get_equipments_touch.py')
        spec = importlib.util.spec_from_file_location('get_equipments_touch',
                                                      path)
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        decode = module.decode_conditions
        self.assertEqual(decode('CM<6|CP<12'), ['MP < 6 | AP < 12'])
        self.assertEqual(decode('(CM<6|CP<12)&CW>300'),
                         ['MP < 6 | AP < 12', 'Wisdom > 300'])
        self.assertEqual(decode('CW>100&(CP<11|CM<6)'),
                         ['Wisdom > 100', 'AP < 11 | MP < 6'])
        self.assertEqual(decode('CS>20&CV>6'), ['Strength > 20', 'Vitality > 6'])
        # A branch gating something we do not model leaves nothing enforceable.
        self.assertEqual(decode('Pj=48|Pj=49'), [])

    def test_the_touch_items_carry_their_branches(self):
        from fashionistapulp.structure import get_structure, set_current_game_version
        self.addCleanup(set_current_game_version, 'dofus3')
        set_current_game_version('touch')
        structure = get_structure('touch')
        for name, expected in self.KNOWN.items():
            item = structure.get_item_by_name(name)
            with self.subTest(item=name):
                self.assertIsNotNone(item, '%s missing from items_touch.db' % name)
                got = [(structure.get_stat_by_id(stat).name, is_max, value)
                       for branch in item.or_conditions for stat, is_max, value in branch]
                self.assertEqual(sorted(got), sorted(expected))

    def test_the_model_builds_one_selector_per_branch(self):
        from fashionistapulp.structure import get_structure, set_current_game_version
        from fashionistapulp.model import Model
        self.addCleanup(set_current_game_version, 'dofus3')
        set_current_game_version('touch')
        structure = get_structure('touch')
        model = Model()
        with_or = [item for item in model.items_list if item.or_conditions]
        self.assertTrue(with_or, 'no touch item carries an or condition')
        for item in with_or:
            with self.subTest(item=item.name):
                self.assertIn(item.id, model.restrictions.or_branch_constraints)
                for number, branch in enumerate(item.or_conditions):
                    for stat, _is_max, _value in branch:
                        self.assertIn((item.id, number, stat),
                                      model.restrictions.or_condition_contraints)

    @unittest.skipUnless(_pulp_solver_available(), 'no pulp solver available')
    def test_a_solve_that_breaks_every_branch_drops_the_item(self):
        from fashionistapulp.structure import get_structure, set_current_game_version
        from fashionistapulp.model import Model, ModelInput
        self.addCleanup(set_current_game_version, 'dofus3')
        set_current_game_version('touch')
        structure = get_structure('touch')
        options = {'ap_exo': False, 'range_exo': False, 'mp_exo': False,
                   'dofus': True, 'dragoturkey': True, 'seemyool': True,
                   'rhineetle': True, 'prysmaradite': False, 'shields': True,
                   'trophies': True}
        # Professor Xa needs MP under 6 or AP under 12; ask for both above.
        model_input = ModelInput(
            char_level=200,
            base_stats_by_attr={'AP': 7, 'MP': 3, 'Vitality': 0, 'Wisdom': 0,
                                'Strength': 0, 'Intelligence': 0, 'Chance': 0,
                                'Agility': 0},
            minimum_stats={'AP': 12, 'MP': 6},
            locked_equips={}, forbidden_equips=set(),
            objective_values={'str': 50, 'vit': 10, 'ap': 800, 'mp': 600},
            options=options, char_class='Iop',
            stat_points_to_distribute=5 * 199)
        model = Model()
        model.setup(model_input)
        model.run(2)
        self.assertEqual(model.get_solved_status(), 'Optimal')
        result = model.get_result_minimal()
        for item_id in (result.item_per_slot or {}).values():
            item = structure.get_item_by_id(item_id)
            if item is None or not item.or_conditions:
                continue
            self.fail('%s was equipped though neither branch can hold at '
                      '12 AP and 6 MP' % item.name)

    def _solve_with_locked_boots(self, minimum_stats):
        from fashionistapulp.structure import get_structure, set_current_game_version
        from fashionistapulp.model import Model, ModelInput
        from fashionistapulp.dofus_constants import STAT_NAME_TO_KEY
        set_current_game_version('dofus3')
        structure = get_structure('dofus3')
        boots = structure.get_item_by_name('Baleenaboots')
        self.assertIsNotNone(boots)
        self.assertTrue(boots.or_conditions, 'Baleenaboots lost its branches')
        weights = {key: 0 for key in STAT_NAME_TO_KEY.values()}
        weights.update({'str': 50, 'vit': 10, 'ap': 800, 'mp': 600})
        model_input = ModelInput(
            char_level=200,
            # the base a level 200 character brings, as get_base_stats_by_attr
            # hands it to the solver: a condition is read on the final total
            base_stats_by_attr={'AP': 7, 'MP': 3, 'Vitality': 0, 'Wisdom': 0,
                                'Strength': 0, 'Intelligence': 0, 'Chance': 0,
                                'Agility': 0},
            minimum_stats=minimum_stats,
            locked_equips={'boots': boots.id}, forbidden_equips=set(),
            objective_values=weights,
            options={'ap_exo': False, 'range_exo': False, 'mp_exo': False,
                     'dofus': True, 'dragoturkey': True, 'seemyool': True,
                     'rhineetle': True, 'prysmaradite': False, 'shields': True,
                     'trophies': True},
            char_class='Iop', stat_points_to_distribute=5 * 199)
        model = Model()
        model.setup(model_input)
        model.run(2)
        if model.get_solved_status() != 'Optimal':
            return model.get_solved_status(), None, None
        variables = model.problem.pulp_vars
        return (model.get_solved_status(),
                variables['stat_%d' % structure.get_stat_by_name('AP').id].varValue,
                variables['stat_%d' % structure.get_stat_by_name('MP').id].varValue)

    @unittest.skipUnless(_pulp_solver_available(), 'no pulp solver available')
    def test_a_locked_item_keeps_one_of_its_branches_true(self):
        # Dofus 3 carries the disjunctions on 37 items. Baleenaboots wants
        # 11 AP or less, or 5 MP or less. Locked into a build, the solver has
        # to hold one of the two, and asking for both above leaves neither.
        status, ap, mp = self._solve_with_locked_boots({})
        self.assertEqual('Optimal', status)
        self.assertTrue(ap <= 11 or mp <= 5, 'both branches broken at %s AP %s MP'
                        % (ap, mp))

        status, ap, mp = self._solve_with_locked_boots({'AP': 12})
        self.assertEqual('Optimal', status)
        self.assertEqual(12, ap)
        self.assertLessEqual(mp, 5, 'the AP branch is out, the MP one has to hold')

        status, _ap, _mp = self._solve_with_locked_boots({'AP': 12, 'MP': 6})
        self.assertEqual('Infeasible', status,
                         'the boots cannot be worn at 12 AP and 6 MP')


class SolvedBuildIsWearableTests(TestCase):
    """What the solver hands back has to be a build a character could wear."""

    # One of each, except rings, which a character wears two of.
    SLOT_LIMITS = {'Hat': 1, 'Cloak': 1, 'Amulet': 1, 'Belt': 1, 'Boots': 1,
                   'Shield': 1, 'Weapon': 1, 'Pet': 1, 'Ring': 2, 'Dofus': 6}

    def _solve(self, version, char_class, level, aspects, with_solution=False):
        from django.test import RequestFactory
        from django.contrib.auth.models import User
        from fashionistapulp.structure import set_current_game_version
        from chardata.coaching_view import create_build
        from chardata.solution import get_solution
        set_current_game_version(version)
        self.addCleanup(set_current_game_version, 'dofus3')
        tag = '%s%s%d' % (version, char_class, level)
        owner = User.objects.create_user(
            'wear%s' % tag, '%s@t.local' % tag, 'pw-42-solid')
        request = RequestFactory().post('/')
        request.user = owner
        char = create_build(request, char_class, level, aspects, version)
        self.client.force_login(owner)
        prefix = '' if version == 'dofus3' else '/' + version
        self.client.get('%s/fashion/%d/' % (prefix, char.pk))
        char.refresh_from_db()
        solution = get_solution(char)
        self.assertIsNotNone(solution, version)
        worn = [ri for ri in solution.item_list if ri.item_added]
        return (worn, solution) if with_solution else worn

    def _check(self, version, char_class, level, aspects):
        from collections import Counter
        worn = self._solve(version, char_class, level, aspects)
        self.assertGreaterEqual(len(worn), 8, version)
        too_high = [(ri.name, ri.level) for ri in worn
                    if ri.level is not None and ri.level > level]
        self.assertEqual([], too_high, '%s: worn above the character level' % version)
        removed = [ri.name for ri in worn if getattr(ri, 'removed', False)]
        self.assertEqual([], removed, '%s: a removed item was equipped' % version)
        slots = Counter(ri.type for ri in worn)
        over = {slot: n for slot, n in slots.items()
                if n > self.SLOT_LIMITS.get(slot, 1)}
        self.assertEqual({}, over, '%s: more pieces than slots' % version)

    @unittest.skipUnless(_pulp_solver_available(), 'no pulp solver available')
    def test_a_low_level_build_is_wearable(self):
        self._check('dofus3', 'Iop', 50, {'str'})

    @unittest.skipUnless(_pulp_solver_available(), 'no pulp solver available')
    def test_an_endgame_build_is_wearable(self):
        self._check('dofus3', 'Cra', 200, {'agi'})

    @unittest.skipUnless(_pulp_solver_available(), 'no pulp solver available')
    def test_a_retro_build_is_wearable(self):
        self._check('retro', 'Iop', 100, {'str'})

    @unittest.skipUnless(_pulp_solver_available(), 'no pulp solver available')
    def test_a_fresh_build_never_wears_a_default_forbidden_item(self):
        # The default exclusions hide GM gear and joke pieces.
        from chardata.lock_forbid import (DEFAULT_EXCLUSION_ANKAMA_IDS,
                                          DEFAULT_EXCLUSION_ANKAMA_IDS_BY_VERSION)
        for version in ('dofus3', 'retro'):
            banned = set(DEFAULT_EXCLUSION_ANKAMA_IDS) | set(
                DEFAULT_EXCLUSION_ANKAMA_IDS_BY_VERSION.get(version, []))
            worn = self._solve(version, 'Iop', 200, {'str'})
            with self.subTest(version=version):
                self.assertEqual(
                    [], [ri.name for ri in worn
                         if getattr(ri, 'ankama_id', None) in banned])

    def test_no_default_exclusion_hides_another_version_item(self):
        # The global list is written with Dofus 3 ankama ids, and an id is not an
        # identity across versions; an id absent from a version hides nothing.
        from fashionistapulp.structure import get_structure
        from fashionistapulp.fashion_util import is_same_item_name
        from chardata.lock_forbid import DEFAULT_EXCLUSION_ANKAMA_IDS
        reference = get_structure('dofus3')
        known = {}
        for ankama_id in DEFAULT_EXCLUSION_ANKAMA_IDS:
            item = reference.get_item_by_ankama_id(ankama_id)
            if item is not None:
                known[ankama_id] = item.name
        self.assertGreater(len(known), 10, 'no id left to compare')
        for version in ('beta', 'dofus2', 'retro', 'touch'):
            structure = get_structure(version)
            clashes = []
            for ankama_id, reference_name in known.items():
                item = structure.get_item_by_ankama_id(ankama_id)
                if item is None:
                    continue
                if not is_same_item_name(item.name, reference_name):
                    clashes.append((ankama_id, reference_name, item.name))
            with self.subTest(version=version):
                self.assertEqual([], clashes)

    def _check_equip_conditions(self, version, char_class, level, aspects):
        """An equip condition is read on the final total, the item's own bonus
        counted."""
        from fashionistapulp.structure import get_structure
        worn, solution = self._solve(version, char_class, level, aspects,
                                     with_solution=True)
        structure = get_structure(version)
        totals = solution.get_stats_total()
        gates = 0
        broken = []
        for result_item in worn:
            item = structure.get_item_by_id(getattr(result_item, 'id', None))
            if item is None:
                continue
            for stat_id, needed in getattr(item, 'min_stats_to_equip', []):
                stat = structure.get_stat_by_id(stat_id)
                if stat is None:
                    continue
                gates += 1
                if totals.get(stat.key, 0) < needed:
                    broken.append('%s needs %s >= %d, the build has %d'
                                  % (result_item.name, stat.key, needed,
                                     totals.get(stat.key, 0)))
            for stat_id, cap in getattr(item, 'max_stats_to_equip', []):
                stat = structure.get_stat_by_id(stat_id)
                if stat is None:
                    continue
                gates += 1
                if totals.get(stat.key, 0) > cap:
                    broken.append('%s needs %s <= %d, the build has %d'
                                  % (result_item.name, stat.key, cap,
                                     totals.get(stat.key, 0)))
            for branch in getattr(item, 'or_conditions', None) or []:
                gates += 1
                held = []
                for stat_id, is_max, value in branch:
                    stat = structure.get_stat_by_id(stat_id)
                    if stat is None:
                        continue
                    reached = totals.get(stat.key, 0)
                    held.append(reached <= value if is_max else reached >= value)
                if all(held):
                    break
            else:
                if getattr(item, 'or_conditions', None):
                    broken.append('%s is worn though none of its %d branches '
                                  'holds' % (result_item.name,
                                             len(item.or_conditions)))
        return gates, broken

    @unittest.skipUnless(_pulp_solver_available(), 'no pulp solver available')
    def test_the_build_can_put_its_own_gated_gear_on(self):
        # Touch and Retro reach for the gated pieces; Dofus 3 is where the
        # disjunctions are, 37 items of them.
        exercised = 0
        for version, char_class in (('touch', 'Iop'), ('retro', 'Iop'),
                                    ('dofus3', 'Iop')):
            gates, broken = self._check_equip_conditions(
                version, char_class, 200, {'str'})
            exercised += gates
            with self.subTest(version=version):
                self.assertEqual([], broken)
        self.assertGreater(exercised, 0, 'no equip condition was exercised')

    def _check_set_bonus(self, version):
        """The solver counts the set pieces itself and adds the matching tier
        bonus."""
        from collections import Counter
        from fashionistapulp.structure import get_structure
        worn, solution = self._solve(version, 'Iop', 200, {'str'},
                                     with_solution=True)
        structure = get_structure(version)

        actual = Counter(ri.set for ri in worn if ri.set)
        expected = {set_id: n for set_id, n in actual.items() if n > 1}
        reported = {rs.id: rs.number_of_items for rs in solution.sets}
        self.assertEqual(expected, reported,
                         '%s counted its set pieces wrong' % version)

        for result_set in solution.sets:
            item_set = structure.get_set_by_id(result_set.id)
            declared = item_set.bonus_per_num_items.get(
                result_set.number_of_items, {})
            self.assertEqual(dict(declared), dict(result_set.get_bonus()),
                             '%s: %s at %d pieces'
                             % (version, result_set.name,
                                result_set.number_of_items))

        manual = Counter()
        for result_item in worn:
            manual.update(result_item.stats)
        for result_set in solution.sets:
            manual.update(result_set.get_bonus())
        options = solution.input['options']
        for stat_key, option in (('ap', 'ap_exo'), ('mp', 'mp_exo'),
                                 ('range', 'range_exo')):
            if options.get(option):
                manual[stat_key] += 1
        gear = solution.get_stats_gear()
        drifted = {key for key in set(manual) | set(gear)
                   if manual.get(key, 0) != gear.get(key, 0)}
        self.assertEqual(set(), drifted,
                         '%s gear total is not items plus set bonuses' % version)
        return len(solution.sets)

    @unittest.skipUnless(_pulp_solver_available(), 'no pulp solver available')
    def test_a_build_gets_the_set_bonus_for_the_pieces_it_wears(self):
        exercised = 0
        for version in ('dofus3', 'retro', 'touch'):
            with self.subTest(version=version):
                exercised += self._check_set_bonus(version)
        self.assertGreater(exercised, 0, 'no set bonus was exercised')


class DistributedPointsAreAffordableTests(TestCase):
    """When the solver spends the characteristic points itself, a character of
    that level must be able to afford the bill. Each version prices its own."""

    TIER_COST = [0.5, 1, 2, 3, 4, 5]

    def _bill(self, caps_for_stat, scrolled, spent):
        """Capital the game charges for `spent` points, and any left unpriced."""
        from fashionistapulp.dofus_constants import tier_widths_after_scroll
        widths = tier_widths_after_scroll(caps_for_stat, scrolled)
        remaining, cost = spent, 0.0
        for index in range(6):
            width = widths[index]
            take = remaining if width is None else min(remaining, width)
            cost += take * self.TIER_COST[index]
            remaining -= take
            if remaining <= 0:
                break
        return cost, remaining

    def _solve_distributing(self, version, char_class, level):
        from django.test import RequestFactory
        from django.contrib.auth.models import User
        from fashionistapulp.structure import set_current_game_version
        from chardata.coaching_view import create_build
        from chardata.solution import get_solution
        set_current_game_version(version)
        self.addCleanup(set_current_game_version, 'dofus3')
        tag = '%s%s%d' % (version, char_class, level)
        owner = User.objects.create_user('spend%s' % tag, 'spend%s@t.local' % tag,
                                         'pw-42-solid')
        request = RequestFactory().post('/')
        request.user = owner
        char = create_build(request, char_class, level, {'str'}, version)
        char.allow_points_distribution = True
        char.save()
        self.client.force_login(owner)
        prefix = '' if version == 'dofus3' else '/' + version
        self.client.get('%s/fashion/%d/' % (prefix, char.pk))
        char.refresh_from_db()
        solution = get_solution(char)
        self.assertIsNotNone(solution, version)
        return solution

    @unittest.skipUnless(_pulp_solver_available(), 'no pulp solver available')
    def test_the_character_can_pay_for_the_points_the_solver_spends(self):
        from fashionistapulp.dofus_constants import (BASE_STATS, STAT_KEY_TO_NAME,
                                                     get_soft_caps_for,
                                                     scrolls_push_cost_curve)
        for version, char_class, level in (('dofus3', 'Iop', 200),
                                           ('retro', 'Iop', 200),
                                           ('touch', 'Iop', 200)):
            with self.subTest(version=version):
                solution = self._solve_distributing(version, char_class, level)
                spent_by_stat = solution.get_stats() or {}
                entered = solution.input['base_stats_by_attr']
                caps = get_soft_caps_for(version, char_class)
                pushes = scrolls_push_cost_curve(version)
                budget = 5 * (level - 1)
                total = 0.0
                unpriced = 0
                for key in BASE_STATS:
                    spent = spent_by_stat.get(key, 0) or 0
                    if spent <= 0:
                        continue
                    scrolled = entered.get(STAT_KEY_TO_NAME[key], 0) if pushes else 0
                    cost, left = self._bill(caps[key], scrolled, spent)
                    total += cost
                    unpriced += left
                self.assertEqual(0, unpriced, '%s priced no tier for some points'
                                              % version)
                self.assertLessEqual(total, budget, version)
                self.assertGreater(total, budget * 0.5, version)


class SetMaxCapTests(TestCase):
    """Cire Momore's Curse is the one set that caps stats instead of raising them:
    the more pieces worn, the lower the MP, range and summon ceiling."""

    SET_NAME = "Cire Momore's Curse"
    SLOT_BY_ITEM = [('Heavy Burden', 'amulet'), ("Cire's Sorrow", 'hat'),
                    ('Howling Souls', 'cloak'), ('Eternal Chase', 'belt'),
                    ('Signet of Fate', 'ring1'), ('Claymomore', 'weapon')]

    def _solve_wearing(self, pieces):
        from django.test import RequestFactory
        from django.contrib.auth.models import User
        from fashionistapulp.structure import (set_current_game_version,
                                               get_structure)
        from chardata.coaching_view import create_build
        from chardata.solution import get_solution
        from chardata.lock_forbid import set_inclusions_dict_and_check_exclusions
        set_current_game_version('dofus3')
        self.addCleanup(set_current_game_version, 'dofus3')
        structure = get_structure('dofus3')
        owner = User.objects.create_user('cap%d' % pieces, 'cap%d@t.local' % pieces,
                                         'pw-42-solid')
        request = RequestFactory().post('/')
        request.user = owner
        char = create_build(request, 'Iop', 200, {'str'}, 'dofus3')

        wanted = self.SLOT_BY_ITEM[:pieces]
        inclusions = {slot: '' for _, slot in self.SLOT_BY_ITEM}
        for name, slot in wanted:
            inclusions[slot] = str(structure.get_item_by_name(name).id)
        set_inclusions_dict_and_check_exclusions(char, inclusions)

        self.client.force_login(owner)
        self.client.get('/fashion/%d/' % char.pk)
        char.refresh_from_db()
        solution = get_solution(char)
        self.assertIsNotNone(solution, '%d locked pieces gave no solution' % pieces)
        equipped = {ri.name for ri in solution.item_list if ri.item_added}
        self.assertEqual(set(), {name for name, _ in wanted} - equipped,
                         'the locked pieces did not all reach the build')
        return solution

    @unittest.skipUnless(_pulp_solver_available(), 'no pulp solver available')
    def test_the_curse_caps_the_build_it_is_worn_on(self):
        from fashionistapulp.structure import get_structure
        structure = get_structure('dofus3')
        item_set = structure.get_set_by_name(self.SET_NAME)
        caps_by_tier = {}
        for num_items, stat_id, max_value in item_set.max_caps:
            stat = structure.get_stat_by_id(stat_id)
            caps_by_tier.setdefault(num_items, {})[stat.key] = max_value

        # At two pieces MP stops at 4, at six it drops to 2, under the 3 MP a
        # character starts with.
        for pieces in (2, 6):
            with self.subTest(pieces=pieces):
                totals = self._solve_wearing(pieces).get_stats_total()
                caps = caps_by_tier[pieces]
                self.assertTrue(caps, 'no cap declared at %d pieces' % pieces)
                over = {key: (totals.get(key), cap) for key, cap in caps.items()
                        if totals.get(key, 0) > cap}
                self.assertEqual({}, over)
        self.assertEqual(2, caps_by_tier[6]['mp'])


