class WeaponTypeDisplayTests(TestCase):
    """A weapon with no standard type (magnifying glass, fishing rod) shows its AP
    line without a type prefix. evolve_result_item reads the global game version."""

    def _damage_head(self, item_name):
        from fashionistapulp.structure import (get_structure,
                                               set_current_game_version)
        from fashionistapulp.modelresult import ModelResultItem
        from chardata.solution_result import evolve_result_item
        # evolve_result_item reads the process-wide version, so state it here:
        # under --parallel a neighbour in the same worker leaves it elsewhere
        # and the item comes back with no damage text at all.
        self.addCleanup(set_current_game_version, 'dofus3')
        set_current_game_version('dofus3')
        item = get_structure('dofus3').get_item_by_name(item_name)
        self.assertIsNotNone(item, 'missing test fixture item %r' % item_name)
        result_item = ModelResultItem(item)
        evolve_result_item(result_item)
        return result_item.damage_text.split('<br>')[0]

    def test_untyped_weapon_has_no_placeholder_prefix(self):
        head = self._damage_head('Magnifying Glass')
        self.assertNotIn('Unknown Weapon Type', head)
        self.assertNotIn('DefaultName', head)
        self.assertTrue(head.startswith('AP:'), head)

    def test_typed_weapon_keeps_its_type_prefix(self):
        from fashionistapulp.structure import get_structure
        st = get_structure('dofus3')
        sword_name = next(
            name for name, w in st.weapons_dict_by_name.items()
            if getattr(st.get_weapon_type_by_id(w.weapon_type), 'name', None) == 'Sword')
        head = self._damage_head(sword_name)
        self.assertIn('(Sword)', head)

class ForgemagieRuneRosterTests(SimpleTestCase):
    """The rune roster of the modern game; Touch forked before these runes."""

    def _stat(self, version, key):
        from chardata.forgemagie_data import get_fm_stat
        return get_fm_stat(version, key)

    def test_the_modern_game_has_a_ra_tier_on_the_resists(self):
        for key in ('neutres', 'earthres', 'fireres', 'waterres', 'airres',
                    'crires', 'pshres', 'pshdam'):
            with self.subTest(stat=key):
                tiers = dict(self._stat('dofus3', key)['tiers'])
                self.assertEqual(tiers.get('Ra'), 10)

    def test_reflects_can_take_a_pa_rune(self):
        self.assertEqual(dict(self._stat('dofus3', 'ref')['tiers']).get('Pa'), 3)

    def test_the_percent_melee_and_ranged_resists_weigh_ten(self):
        for key in ('respermee', 'resperran'):
            with self.subTest(stat=key):
                self.assertEqual(self._stat('dofus3', key)['density'], 10)

    def test_percent_weapon_resist_has_no_rune_because_the_game_has_none(self):
        self.assertEqual(self._stat('dofus3', 'resperwea')['tiers'], [])

    def test_touch_weights_match_its_own_encyclopedia(self):
        # From the Touch encyclopedia's per-rune "Poids de Forgemagie" field.
        for key in ('fireres', 'crires', 'pshres', 'pshdam', 'firedam'):
            with self.subTest(stat=key):
                self.assertNotIn('Ra', dict(self._stat('touch', key)['tiers']))
        vit = self._stat('touch', 'vit')
        self.assertEqual((vit['density'], vit['tiers']),
                         (0.2, [('', 5), ('Pa', 15), ('Ra', 50)]))
        self.assertEqual(self._stat('touch', 'wis')['density'], 1)
        self.assertEqual(self._stat('touch', 'ch')['density'], 10)
        heals = self._stat('touch', 'heals')
        self.assertEqual((heals['density'], heals['tiers']),
                         (10, [('', 1), ('Pa', 3)]))

    def test_touch_dropped_traps_and_reflect_in_1_57(self):
        for key in ('ref', 'trapdam', 'trapdamper'):
            with self.subTest(stat=key):
                self.assertIsNone(self._stat('touch', key))
        # The PC game keeps all three.
        for key in ('ref', 'trapdam', 'trapdamper'):
            with self.subTest(stat=key):
                self.assertIsNotNone(self._stat('dofus3', key))


class RuneNamesMatchTheGameTests(SimpleTestCase):
    """Every rune the page names has to exist in that version's own item table.
    The page used to print Rune Ga PO, Rune Pi Per and a dozen other spellings
    the game does not use, so a player searching the market found nothing."""

    RUNE_TYPE = 133
    RUNE_TYPE_ID = 78

    @staticmethod
    def _root():
        from fashionistapulp.fashionista_config import get_fashionista_path
        return get_fashionista_path()

    def _resources(self, *parts):
        import json
        path = os.path.join(self._root(), 'itemscraper', *parts)
        if not os.path.exists(path):
            self.skipTest('%s not in this checkout' % path)
        with open(path, encoding='utf-8') as handle:
            data = json.load(handle)
        items = data if isinstance(data, list) else data['items']
        return {item['name'] for item in items
                if isinstance(item, dict)
                and (item.get('type') or {}).get('id') == self.RUNE_TYPE}

    def _touch(self):
        import json
        path = os.path.join(self._root(), 'itemscraper', 'touch_raw',
                            'Items_fr.json')
        if not os.path.exists(path):
            self.skipTest('touch item table not in this checkout')
        with open(path, encoding='utf-8') as handle:
            data = json.load(handle)
        return {item['nameId'] for item in data.values()
                if isinstance(item, dict)
                and item.get('typeId') == self.RUNE_TYPE_ID
                and isinstance(item.get('nameId'), str)}

    def _retro(self):
        import json
        path = os.path.join(self._root(), 'itemscraper', 'retro_raw',
                            'items_fr.json')
        if not os.path.exists(path):
            self.skipTest('retro item table not in this checkout')
        with open(path, encoding='utf-8') as handle:
            data = json.load(handle)
        return {item['n'] for item in data['I']['u'].values()
                if isinstance(item, dict)
                and item.get('t') == self.RUNE_TYPE_ID
                and isinstance(item.get('n'), str)}

    def _page_names(self, version):
        from chardata.forgemagie_data import get_fm_stats
        names = set()
        for stat in get_fm_stats(version).values():
            for tier, _bonus in stat['tiers']:
                names.add(' '.join(part for part in ('Rune', tier, stat['rune'])
                                   if part))
        return names

    def _sources(self):
        return (
            ('dofus3', lambda: self._resources('all_resources_fr.json')),
            ('beta', lambda: self._resources('beta', 'all_resources_fr.json')),
            ('dofus2', lambda: self._resources('dofus2', 'all_resources_fr.json')),
            ('touch', self._touch),
            ('retro', self._retro),
        )

    def test_no_version_names_a_rune_the_game_does_not_have(self):
        for version, reader in self._sources():
            with self.subTest(version=version):
                unknown = sorted(self._page_names(version) - reader())
                self.assertEqual(unknown, [])

    # The other direction. A rune of the game that the stat table does not
    # name is either not a stat rune or a duplicate of one already named, and
    # every one of them is listed here with why. Anything else appearing is a
    # rune the page would silently never offer.
    OUT_OF_THE_STAT_TABLE = {
        # Raise no characteristic; the page carries them separately.
        'Rune de chasse', 'Rune de Signature',
        # Account-bound twins of Ga Pa, Ga Pme and Po, same power, so naming
        # them again would offer the same rune twice.
        'Rune Gata Pa', 'Rune Gata Pme', 'Rune Gata Po',
        # Raises a shield's rank, not a characteristic (the game says so).
        'Rune de fortification mineure', 'Rune de fortification moyenne',
        'Rune de fortification majeure',
        # Power 3 like Rune Vi, but which characteristic it feeds is not in
        # the 1.29 files this checkout has, so it stays out rather than be
        # guessed at.
        'Rune Vie',
    }

    def test_no_version_leaves_a_stat_rune_out(self):
        for version, reader in self._sources():
            with self.subTest(version=version):
                missed = sorted(reader() - self._page_names(version)
                                - self.OUT_OF_THE_STAT_TABLE)
                self.assertEqual(missed, [])

    def test_the_retro_trap_rune_has_its_pa_tier(self):
        # Rune Pa Pi is in the 1.29 item table at power 3, and the page used to
        # offer the trap line its base rune only.
        from chardata.forgemagie_data import get_fm_stat
        self.assertEqual(get_fm_stat('retro', 'trapdam')['tiers'],
                         [('', 1), ('Pa', 3)])
        self.assertIn('Rune Pa Pi', self._page_names('retro'))


class SmithmagicOddsTests(TestCase):
    """The odds model is fitted on two runs measured on a Rhineetle Ring at a
    perfect roll: a Ra Vi with vitality 50 short of its max gives a 20 to 25%
    critical, and a % spell damage exo with no sink about 10%. The knobs are
    tunable on purpose, so the fit is checked rather than trusted."""

    PAGE = os.path.join(os.path.dirname(__file__), 'templates', 'chardata',
                        'forgemagie.html')

    MATHS = ('round2', 'statInfo', 'overWeightAt', 'overWeightAfter',
             'isOnePercentThrow', 'lineCeiling', 'wouldExceedCap',
             'totalItemWeight', 'passFactorRuneLimit', 'passFactorFill',
             'belowNaturalMin', 'passFactorWeight', 'passFactorSink',
             'chancesFor', 'lossPool', 'pointsThatFit', 'pointsAboveMin',
             'pickLossLine')

    def _function(self, source, name):
        start = source.index('\n        function %s(' % name) + 1
        depth = 0
        index = source.index('{', start)
        while True:
            if source[index] == '{':
                depth += 1
            elif source[index] == '}':
                depth -= 1
                if depth == 0:
                    return source[start:index + 1]
            index += 1

    def _model(self):
        page = io.open(self.PAGE, encoding='utf-8').read()
        odds = re.search(r'var FM_ODDS = \{.*?\};', page, re.S).group(0)
        return '\n'.join([odds] + [self._function(page, name)
                                   for name in self.MATHS])

    def _config(self):
        from chardata.forgemagie_data import (
            OVER_WEIGHT_CAP, get_fm_stats, get_one_percent_over_weight)
        stats = {}
        for key, fm_stat in get_fm_stats('dofus3').items():
            stats[key] = {
                'density': fm_stat['density'],
                'tiers': [{'name': tier, 'bonus': bonus,
                           'weight': round(bonus * fm_stat['density'], 2)}
                          for tier, bonus in fm_stat['tiers']],
            }
        return {'overCap': OVER_WEIGHT_CAP,
                'onePercentOverWeight': get_one_percent_over_weight('dofus3'),
                'stats': stats}

    def _ring_rows(self):
        from fashionistapulp.structure import get_structure
        structure = get_structure()
        item = structure.get_item_by_name('Rhineetle Ring')
        self.assertIsNotNone(item)
        ranges = getattr(item, 'stat_ranges', {}) or {}
        rows = []
        for stat_id, value in item.stats:
            stat = structure.get_stat_by_id(stat_id)
            low = ranges.get(stat_id, (None, None))[0]
            rows.append({'key': stat.key, 'value': int(round(value)),
                         'min': int(round(low)) if low is not None else 0,
                         'max': int(round(value)), 'target': 0, 'exo': False})
        return rows

    def _run(self, driver):
        node = shutil.which('node')
        if node is None:
            self.skipTest('node is not installed')
        source = '%s\nvar config = %s;\nvar rows = %s;\n%s' % (
            self._model(), json.dumps(self._config()),
            json.dumps(self._ring_rows()), driver)
        with tempfile.NamedTemporaryFile('w', suffix='.js', encoding='utf-8',
                                         delete=False) as handle:
            handle.write(source)
            name = handle.name
        try:
            done = subprocess.run([node, name], capture_output=True, text=True)
        finally:
            os.unlink(name)
        self.assertEqual(0, done.returncode, done.stderr[-800:])
        return json.loads(done.stdout)

    def test_the_two_measured_runs_still_read_what_they_measured(self):
        read = self._run(
            "var session = {rows: rows, sink: 0};"
            "var vit = rows.filter(function (r) { return r.key === 'vit'; })[0];"
            "vit.value -= 50;"
            "var raVi = config.stats.vit.tiers.filter("
            "    function (t) { return t.bonus === 50; })[0];"
            "var short = chancesFor(vit, raVi);"
            "vit.value += 50;"
            "var exo = {key: 'perspedam', value: 0, min: 0, max: 0,"
            "           target: 0, exo: true};"
            "rows.push(exo);"
            "var spell = chancesFor(exo, config.stats.perspedam.tiers[0]);"
            "console.log(JSON.stringify({vitality: short.sc,"
            "                            spellDamage: spell.sc,"
            "                            weight: totalItemWeight()}));")
        self.assertAlmostEqual(360, read['weight'], places=2)
        self.assertGreaterEqual(read['vitality'], 0.20)
        self.assertLessEqual(read['vitality'], 0.25)
        self.assertGreaterEqual(read['spellDamage'], 0.08)
        self.assertLessEqual(read['spellDamage'], 0.12)

    def test_a_one_percent_line_has_no_neutral_success_at_all(self):
        # FenixAP asked whether an SN can happen on those lines. It cannot:
        # this simulator has three outcomes and on a 1% line only two are
        # reachable.
        read = self._run(
            "var session = {rows: rows, sink: 0};"
            "var out = {};"
            "['summon', 'ap', 'mp'].forEach(function (key) {"
            "    if (!config.stats[key]) { return; }"
            "    var row = {key: key, value: 0, min: 0, max: 0,"
            "               target: 0, exo: true};"
            "    rows.push(row);"
            "    out[key] = chancesFor(row, config.stats[key].tiers[0]);"
            "});"
            "console.log(JSON.stringify(out));")
        self.assertTrue(read, 'no one-percent line was exercised')
        for key, chances in read.items():
            with self.subTest(stat=key):
                self.assertAlmostEqual(0.01, chances['sc'], places=6)
                self.assertEqual(0, chances['sn'])
                self.assertAlmostEqual(0.99, chances['ec'], places=6)

    def test_the_sink_stops_paying_at_a_quarter(self):
        # It scales with how much of the rune the sink covers and then stops,
        # however deep the sink gets.
        read = self._run(
            "var exo = {key: 'perspedam', value: 0, min: 0, max: 0,"
            "           target: 0, exo: true};"
            "rows.push(exo);"
            "var tier = config.stats.perspedam.tiers[0];"
            "var session = {rows: rows, sink: 0};"
            "var out = {};"
            "[0, 0.25, 0.5, 1, 2, 10].forEach(function (share) {"
            "    session.sink = tier.weight * share;"
            "    out[String(share)] = chancesFor(exo, tier).sc;"
            "});"
            "console.log(JSON.stringify(out));")
        dry = read['0']
        self.assertGreater(dry, 0)
        self.assertLess(read['0.25'], read['0.5'])
        self.assertLess(read['0.5'], read['1'])
        for share in ('1', '2', '10'):
            with self.subTest(share=share):
                self.assertAlmostEqual(1.25, read[share] / dry, places=6)

    def test_a_critical_failure_spares_the_line_being_raised(self):
        # FenixAP asked that the line you are raising drop less often than the
        # rest. It carries a quarter of their weight in the draw.
        page = io.open(self.PAGE, encoding='utf-8').read()
        share = re.search(r'thrownLineShare:\s*([0-9.]+)', page)
        self.assertIsNotNone(share, 'the workbench no longer spares the line')
        self.assertAlmostEqual(0.25, float(share.group(1)))

    def test_a_loss_is_drawn_among_the_lines_not_taken_from_the_heaviest(self):
        # It used to be the heaviest line the rune could reach, every single
        # throw, which ate the crit line of a Volkorne 100% of the time.
        read = self._run(
            "var session = {rows: rows, sink: 0};"
            "var thrown = 0;"  # the line being raised: it resists, not escapes
            "var pool = lossPool(-1);"
            "var counts = {};"
            "var trials = 20000;"
            "for (var i = 0; i < trials; i++) {"
            "    var pick = pickLossLine(pool, thrown);"
            "    var key = session.rows[pick].key;"
            "    counts[key] = (counts[key] || 0) + 1;"
            "}"
            "console.log(JSON.stringify({counts: counts, trials: trials,"
            "                            pool: pool.length,"
            "                            thrown: session.rows[thrown].key}));")
        counts = read['counts']
        trials = float(read['trials'])
        self.assertGreater(read['pool'], 1, 'the ring offers a single line')
        self.assertGreater(len(counts), 1,
                           'every loss still lands on one line: %s' % counts)
        heaviest = max(counts.values()) / trials
        self.assertLess(heaviest, 0.95,
                        'one line still takes nearly every loss: %s' % counts)
        # And the line being raised is the one it spares.
        spared = counts.get(read['thrown'], 0) / trials
        even = 1.0 / read['pool']
        self.assertLess(spared, even,
                        'the thrown line is not spared: %s' % counts)

    def test_a_sink_makes_the_same_throw_easier(self):
        read = self._run(
            "var exo = {key: 'perspedam', value: 0, min: 0, max: 0,"
            "           target: 0, exo: true};"
            "rows.push(exo);"
            "var tier = config.stats.perspedam.tiers[0];"
            "var session = {rows: rows, sink: 0};"
            "var dry = chancesFor(exo, tier).sc;"
            "session.sink = tier.weight;"
            "console.log(JSON.stringify({dry: dry,"
            "                            wet: chancesFor(exo, tier).sc}));")
        self.assertGreater(read['wet'], read['dry'])


class OnePercentOverWeightTests(TestCase):
    """A line only lands 30 weight or more past the item's own roll on a
    critical, so the page reads the threshold instead of a list of stat
    keys."""

    ONE_POINT_AT_OR_PAST = ('ap', 'mp', 'range', 'summon')
    ONE_POINT_UNDER = ('perspedam', 'dam', 'ch', 'vit', 'str')

    def test_the_lines_players_call_one_percent_reach_the_threshold(self):
        from chardata.forgemagie_data import (get_fm_stat,
                                              get_one_percent_over_weight)
        for key in self.ONE_POINT_AT_OR_PAST:
            with self.subTest(stat=key):
                self.assertGreaterEqual(get_fm_stat('dofus3', key)['density'],
                                        get_one_percent_over_weight('dofus3'))

    def test_a_single_light_exo_stays_under_it(self):
        from chardata.forgemagie_data import (get_fm_stat,
                                              get_one_percent_over_weight)
        for key in self.ONE_POINT_UNDER:
            with self.subTest(stat=key):
                self.assertLess(get_fm_stat('dofus3', key)['density'],
                                get_one_percent_over_weight('dofus3'))

    def test_spell_damage_crosses_it_on_its_second_point(self):
        from chardata.forgemagie_data import (get_fm_stat,
                                              get_one_percent_over_weight)
        density = get_fm_stat('dofus3', 'perspedam')['density']
        threshold = get_one_percent_over_weight('dofus3')
        self.assertLess(density, threshold)
        self.assertGreaterEqual(2 * density, threshold)

    def test_every_ruleset_answers_with_its_own_threshold(self):
        from chardata.forgemagie_data import get_one_percent_over_weight
        for version in ('dofus3', 'beta', 'dofus2', 'touch', 'retro'):
            with self.subTest(version=version):
                self.assertGreater(get_one_percent_over_weight(version), 0)

    def test_retro_crit_sits_on_its_own_threshold(self):
        # The Retro crit rune weighs 30 where the modern one weighs 10, so the
        # same rule makes an over-crit a 1% throw on Retro and not elsewhere.
        from chardata.forgemagie_data import (get_fm_stat,
                                              get_one_percent_over_weight)
        self.assertEqual(30, get_fm_stat('retro', 'ch')['density'])
        self.assertEqual(10, get_fm_stat('dofus3', 'ch')['density'])
        self.assertGreaterEqual(get_fm_stat('retro', 'ch')['density'],
                                get_one_percent_over_weight('retro'))

    def test_the_hint_names_the_lines_of_that_version(self):
        # The sentence used to list the modern lines on every version, so a
        # Retro reader never saw its crit and reflect runes, which weigh 30
        # there. It is built from the version's own densities now.
        modern = self.client.get('/forgemagie/',
                                 HTTP_ACCEPT_LANGUAGE='en').content.decode('utf-8')
        retro = self.client.get('/retro/forgemagie/',
                                HTTP_ACCEPT_LANGUAGE='en').content.decode('utf-8')
        self.assertNotIn('Critical Hits, Reflect', modern)
        self.assertIn('Critical Hits', retro.split('only lands on a critical')[1][:200])

    def test_every_version_ships_the_threshold_to_the_page(self):
        for prefix in ('', 'beta/', 'dofus2/', 'touch/', 'retro/'):
            with self.subTest(prefix=prefix):
                body = self.client.get('/%sforgemagie/' % prefix).content.decode('utf-8')
                self.assertIn('onePercentOverWeight', body)
                self.assertNotIn('onePercentExo', body)


class NoStatRuneTests(TestCase):
    """The hunting and signature runes raise no characteristic, so the stat table
    cannot hold them. Both exist in all five versions (ankama items 10057 and
    7508); only the hunting rune's weight is known, and only for the PC game."""

    VERSIONS = (('', 'dofus3'), ('beta/', 'beta'), ('dofus2/', 'dofus2'),
                ('touch/', 'touch'), ('retro/', 'retro'))

    def test_every_version_lists_both_runes(self):
        from chardata.forgemagie_data import get_no_stat_runes
        for _prefix, version in self.VERSIONS:
            with self.subTest(version=version):
                keys = [rune['key'] for rune in get_no_stat_runes(version)]
                self.assertEqual(keys, ['hunting', 'signature'])

    def test_the_signature_rune_never_weighs_anything(self):
        # It goes in with the craft ingredients, so it never enters smithmagic.
        from chardata.forgemagie_data import get_no_stat_runes
        for _prefix, version in self.VERSIONS:
            with self.subTest(version=version):
                signature = get_no_stat_runes(version)[1]
                self.assertEqual(signature['weight'], 0)

    def test_the_hunting_weight_is_stated_only_where_it_is_known(self):
        from chardata.forgemagie_data import get_no_stat_runes
        for version in ('dofus3', 'beta', 'dofus2'):
            with self.subTest(version=version):
                self.assertEqual(get_no_stat_runes(version)[0]['weight'], 5)
        # Touch weighs 2, from a player who checked the table against the game;
        # no file states it. Retro still has nobody to state it.
        self.assertEqual(get_no_stat_runes('touch')[0]['weight'], 2)
        self.assertIsNone(get_no_stat_runes('retro')[0]['weight'])

    def test_touch_can_now_throw_its_hunting_rune(self):
        # A rune with no weight cannot be weighed against the item, so the
        # simulator refused to offer it at all.
        from chardata.forgemagie_view import (LOCALIZED_UI,
                                              _throwable_no_stat_runes)
        labels = LOCALIZED_UI['en']
        touch = [rune['key'] for rune
                 in _throwable_no_stat_runes('touch', labels)]
        self.assertIn('hunting', touch)
        self.assertNotIn('signature', touch)
        retro = [rune['key'] for rune
                 in _throwable_no_stat_runes('retro', labels)]
        self.assertEqual(retro, [])

    def test_the_page_names_both_runes_under_every_version(self):
        for prefix, version in self.VERSIONS:
            with self.subTest(version=version):
                body = self.client.get(
                    '/%sforgemagie/' % prefix,
                    HTTP_ACCEPT_LANGUAGE='en').content.decode('utf-8')
                self.assertIn('Hunting Rune', body)
                self.assertIn('Signature Rune', body)
                self.assertIn('Runes that raise no characteristic', body)

    def test_only_the_hunting_rune_reaches_the_simulator(self):
        # The signature rune goes in at craft time, and a weight this version
        # does not state cannot be weighed against the item.
        from chardata.forgemagie_view import _throwable_no_stat_runes, _ui_text
        text = _ui_text()
        for version, weight in (('dofus3', 5), ('beta', 5), ('dofus2', 5),
                                ('touch', 2)):
            with self.subTest(version=version):
                runes = _throwable_no_stat_runes(version, text)
                self.assertEqual([rune['key'] for rune in runes], ['hunting'])
                self.assertEqual(runes[0]['weight'], weight)
        # Retro is the one left with nobody to state its hunting weight.
        self.assertEqual(_throwable_no_stat_runes('retro', text), [])

    def test_the_page_hands_the_simulator_its_rune(self):
        resp = self.client.get('/forgemagie/', HTTP_ACCEPT_LANGUAGE='en')
        runes = resp.context['js_config']['noStatRunes']
        self.assertEqual([rune['name'] for rune in runes], ['Hunting Rune'])

    def test_an_item_says_whether_it_is_a_weapon(self):
        # The type shown to the reader is translated, so the picker cannot read
        # it to know where the hunting rune may go.
        from fashionistapulp.structure import get_structure
        from chardata.forgemagie_view import _item_payload
        structure = get_structure('dofus3')
        for type_name, expected in (('Weapon', True), ('Hat', False)):
            item = next(item for item in
                        structure.get_unique_items_by_type_and_level(
                            type_name, 200)
                        if not item.removed)
            with self.subTest(type=type_name):
                payload = _item_payload(structure, item, 'en')
                self.assertEqual(payload['is_weapon'], expected)

    def test_only_the_versions_with_transcendence_list_its_runes(self):
        # The simulator carries the transcendence strings on every version, so
        # the box is read from the context, not from the page text.
        for prefix, version in self.VERSIONS:
            with self.subTest(version=version):
                resp = self.client.get('/%sforgemagie/' % prefix,
                                       HTTP_ACCEPT_LANGUAGE='en')
                rows = resp.context['transcendence_rows']
                if version in ('dofus3', 'beta', 'dofus2'):
                    self.assertTrue(rows)
                    vit = [row for row in rows if row['key'] == 'vit']
                    self.assertEqual(len(vit), 1)
                    self.assertTrue(
                        any('Rune Ta Vi' in cell for cell in vit[0]['runes']))
                else:
                    self.assertEqual(rows, [])


class TranscendenceCatalogueTests(SimpleTestCase):
    """The transcendence runes: a rune's weight is what the 101 rule adds to the
    targeted stat's current weight."""

    @classmethod
    def _runes(cls):
        import json
        import chardata
        path = os.path.join(os.path.dirname(chardata.__file__),
                            'forgemagie_transcendance.json')
        with open(path, encoding='utf-8') as fh:
            return json.load(fh)['runes']

    def test_every_rune_carries_a_weight(self):
        runes = self._runes()
        self.assertEqual(len(runes), 81)
        self.assertEqual([r['name_fr'] for r in runes if not r.get('weight')], [])

    def test_the_ladder_and_its_exceptions(self):
        by_name = {r['name_fr']: r for r in self._runes()}
        expected = {
            'Rune Ta Vi': (50, 40), 'Rune Pata Vi': (75, 60),
            'Rune Rata Vi': (100, 80),
            # Cri has no 60 tier, and the percent runes are single-rank.
            'Rune Ta Cri': (1, 40), 'Rune Pata Cri': (2, 80),
            'Rune Ta Ré Per Terre': (2, 80),
        }
        for name, (bonus, weight) in expected.items():
            with self.subTest(rune=name):
                rune = by_name[name]
                self.assertEqual((rune['bonus'], rune['weight']),
                                 (bonus, weight))

    def test_transcendence_stays_out_of_touch_and_retro(self):
        from chardata.forgemagie_transcendance import get_transcendence_runes
        self.assertTrue(get_transcendence_runes('dofus3'))
        self.assertEqual(get_transcendence_runes('touch'), [])
        self.assertEqual(get_transcendence_runes('retro'), [])


class ForgemagiePayloadTests(TestCase):
    """The workbench needs each line's natural minimum roll: under it the game
    gives the line away."""

    def _ring(self):
        from fashionistapulp.structure import get_structure
        return get_structure('dofus3').get_item_by_name('Rhineetle Ring')

    def test_the_payload_carries_the_minimum_roll(self):
        from chardata.forgemagie_view import _item_payload
        from fashionistapulp.structure import get_structure
        structure = get_structure('dofus3')
        stats = {entry['key']: entry
                 for entry in _item_payload(structure, self._ring(), 'en')['stats']}
        self.assertEqual((stats['vit']['min'], stats['vit']['value']), (201, 250))
        self.assertEqual((stats['ch']['min'], stats['ch']['value']), (4, 5))

    def test_the_item_search_uses_the_same_payload(self):
        resp = self.client.get('/forgemagie/items/', {'q': 'Rhineetle Ring'})
        self.assertEqual(resp.status_code, 200)
        items = resp.json()['items']
        self.assertTrue(items)
        stats = {entry['key']: entry for entry in items[0]['stats']}
        self.assertEqual(stats['vit']['min'], 201)


class TranscendenceAdviceTests(SimpleTestCase):
    """One rune per item of a generated build: a transcendence rune locks the
    item, so only the one the build gains most from is worth naming."""

    # A perfect Volkorne ring: 250 vitality is 50 of weight, 100 chance is 100.
    RING = {'vit': 250, 'cha': 100, 'ch': 5, 'waterdam': 20, 'waterresper': 10}

    def _best(self, weights, version='dofus3', stats=None):
        from chardata.transcendence_advice import best_transcendence
        return best_transcendence(version, self.RING if stats is None else stats,
                                  weights)

    def test_it_names_the_rune_the_build_values(self):
        rune = self._best({'vit': 1})
        self.assertEqual((rune['name_fr'], rune['bonus']), ('Rune Ta Vi', 50))

    def test_a_maxed_line_leaves_no_room_for_its_rune(self):
        # 100 chance weighs 100, and the lightest Ta rune weighs 40.
        self.assertIsNone(self._best({'cha': 1}))

    def test_the_cap_picks_the_tier_that_still_fits(self):
        # 5 critical hits weigh 50, so Ta Cri (40) fits and Pata Cri (80) does not.
        self.assertEqual(self._best({'ch': 1})['name_fr'], 'Rune Ta Cri')

    def test_an_empty_line_takes_the_biggest_rune(self):
        # Nothing on the line, so the whole ladder is legal.
        self.assertEqual(self._best({'str': 1})['name_fr'], 'Rune Rata Fo')

    def test_a_stat_the_build_ignores_is_never_suggested(self):
        self.assertIsNone(self._best({'vit': 0, 'cha': 0}))
        self.assertIsNone(self._best({}))

    def test_the_versions_without_transcendence_get_nothing(self):
        for version in ('retro', 'touch'):
            with self.subTest(version=version):
                self.assertIsNone(self._best({'vit': 1}, version=version))

    def test_a_slot_that_takes_no_rune_is_never_advised(self):
        from chardata.transcendence_advice import best_transcendence
        for item_type in ('Pet', 'Dofus'):
            with self.subTest(item_type=item_type):
                self.assertIsNone(best_transcendence('dofus3', self.RING,
                                                     {'str': 1}, item_type))
        for item_type in ('Ring', 'Hat', 'Weapon', None):
            with self.subTest(item_type=item_type):
                self.assertIsNotNone(best_transcendence('dofus3', self.RING,
                                                        {'str': 1}, item_type))


class ReadOnlyStatsWeightsTests(TestCase):
    """Reading the weights with persist=False must not write the char back;
    filling the defaults in normally does re-save it."""

    def _char(self):
        from chardata.models import Char
        return Char.objects.create(
            name='Weights', char_name='w', char_class='Iop', char_build='build',
            level=200, minimum_stats=b'', minimum_crits=b'', stats_weight=b'',
            options=b'', inclusions=b'', exclusions=b'', link_shared=False,
            game_version='dofus3')

    def test_reading_without_persist_leaves_the_char_alone(self):
        from chardata.models import Char
        from chardata.stats_weights import get_stats_weights
        char = self._char()
        before = Char.objects.get(pk=char.pk).modified_time
        weights = get_stats_weights(char, persist=False)
        self.assertTrue(weights)
        self.assertEqual(Char.objects.get(pk=char.pk).modified_time, before)
        self.assertEqual(Char.objects.get(pk=char.pk).stats_weight, b'')

    def test_the_default_still_writes_the_filled_defaults(self):
        from chardata.models import Char
        from chardata.stats_weights import get_stats_weights
        char = self._char()
        get_stats_weights(char)
        self.assertTrue(Char.objects.get(pk=char.pk).stats_weight)


class WeaponCriticalRateTests(SimpleTestCase):
    """Retro states a weapon's critical rate as one hit in X (the Kaiser hammer is
    1/200); Dofus 2 turned the same field into a percentage."""

    def _line(self, version, weapon_type='Hammer', ap=4, crit_chance=200,
              crit_bonus=5):
        from chardata.weapon_header import format_weapon_header
        return format_weapon_header(version, weapon_type, ap, crit_chance,
                                    crit_bonus)

    def test_retro_states_the_rate_as_a_fraction(self):
        line = self._line('retro')
        self.assertIn('1/200', line)
        self.assertNotIn('200%', line)

    def test_the_versions_that_use_a_percentage_keep_it(self):
        for version in ('dofus3', 'beta', 'dofus2', 'touch'):
            with self.subTest(version=version):
                line = self._line(version, crit_chance=30)
                self.assertIn('30%', line)
                self.assertNotIn('1/30', line)

    def test_a_retro_weapon_that_cannot_crit_shows_no_rate(self):
        # The game writes -1 for a weapon that cannot crit.
        line = self._line('retro', crit_chance=-1)
        self.assertNotIn('CH', line)
        self.assertIn('AP: 4', line)

    def test_the_retro_encyclopedia_prints_the_fraction(self):
        from fashionistapulp.structure import get_structure
        from chardata.encyclopedia_view import _get_weapon_detail_lines
        structure = get_structure('retro')
        item = structure.get_item_by_name('Kaiser')
        self.assertIsNotNone(item)
        lines = _get_weapon_detail_lines(structure, [item], 'en')
        self.assertTrue(lines)
        self.assertIn('1/200', lines[0])

    def test_the_encyclopedia_and_the_picker_use_the_same_header(self):
        from chardata import encyclopedia_view
        from chardata import solution_result
        self.assertIs(encyclopedia_view.format_weapon_header,
                      solution_result.format_weapon_header)


class NonElementalWeaponHitTests(SimpleTestCase):
    """A weapon line that is not damage: it pushes, attracts, steals MP, takes AP
    off. The item page and the picker word them through the same code."""

    def _lines(self, version, name):
        from fashionistapulp.structure import get_structure
        from chardata.encyclopedia_view import _get_weapon_detail_lines
        structure = get_structure(version)
        item = structure.get_item_by_name(name)
        self.assertIsNotNone(item, 'missing %s weapon %s' % (version, name))
        return _get_weapon_detail_lines(structure, [item], 'en')

    def test_the_item_page_words_them_instead_of_printing_the_token(self):
        cases = [('dofus3', 'Oddnicall', 'Attracts 2 cells'),
                 ('dofus3', 'Croblade', 'Pushes 1 cells'),
                 ("dofus3", "Blade O'Ven", 'Steals 1 MP'),
                 ('dofus3', 'Treestaff', 'Removes 1 AP'),
                 ('dofus3', 'Crackler Blade', 'Removes 1 MP'),
                 ('dofus2', 'Treestaff', 'Removes 1 AP'),
                 ('touch', 'Treestaff', 'Removes 1 AP')]
        for version, name, expected in cases:
            with self.subTest(version=version, weapon=name):
                lines = self._lines(version, name)
                self.assertIn(expected, lines)
                for line in lines:
                    self.assertNotIn('_', line)

    def test_the_encyclopedia_and_the_picker_word_a_hit_the_same_way(self):
        from chardata import encyclopedia_view
        from chardata import solution_result
        self.assertIs(encyclopedia_view.format_weapon_hit,
                      solution_result.format_weapon_hit)


class InFightAPAndMPRemovalTests(SimpleTestCase):
    """What tells a wielder's +1 AP from a weapon's -1 AP is the is_active flag the
    game sets, not the effect id, which dofusdude renumbers per dump."""

    def _hits(self, version, element):
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path
        connection = sqlite3.connect(
            'file:%s?mode=ro' % get_items_db_path(version), uri=True)
        try:
            return connection.execute(
                'SELECT COUNT(*) FROM weapon_hits WHERE element = ?',
                (element,)).fetchone()[0]
        finally:
            connection.close()

    def test_the_removal_lines_reach_the_solver(self):
        for version, floor in (('dofus3', 40), ('beta', 40), ('dofus2', 30)):
            with self.subTest(version=version):
                self.assertGreaterEqual(self._hits(version, 'removes_ap'), floor)
                self.assertGreaterEqual(self._hits(version, 'removes_mp'), 5)
        # Touch decodes its own client, not dofusdude.
        self.assertGreaterEqual(self._hits('touch', 'removes_ap'), 20)

    def test_the_attract_line_survives_in_every_version_that_has_it(self):
        for version in ('dofus3', 'beta'):
            with self.subTest(version=version):
                self.assertEqual(5, self._hits(version, 'attracts'))

    def test_an_in_fight_effect_never_becomes_a_wielder_bonus(self):
        # The Treestaff removes 1 AP and grants none, but does carry AP Reduction.
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path
        for version in ('dofus3', 'beta', 'dofus2'):
            connection = sqlite3.connect(
                'file:%s?mode=ro' % get_items_db_path(version), uri=True)
            try:
                stats = dict(connection.execute(
                    'SELECT st.name, s.value FROM stats_of_item s'
                    ' JOIN stats st ON st.id = s.stat'
                    ' JOIN items i ON i.id = s.item'
                    " WHERE i.name = 'Treestaff'"))
            finally:
                connection.close()
            with self.subTest(version=version):
                self.assertNotIn('AP', stats)
                self.assertIn('AP Reduction', stats)


class ExclusionsForbidTests(TestCase):
    """Forbidding an item adds an id that's actually in the forbiddable set,
    grouped variants like Gelano included."""

    def _load_forbid_data(self):
        import json
        from django.contrib.auth.models import User
        from chardata.models import Char
        owner = User.objects.create_user('forbidder', 'fb@test.local', 'pw-42-solid')
        char = Char.objects.create(
            name='Forbid', char_name='forbid', char_class='Iop',
            char_build='build', level=200,
            minimum_stats=b'', minimum_crits=b'', stats_weight=b'',
            options=b'', inclusions=b'', exclusions=b'',
            owner=owner, link_shared=False, game_version='dofus3')
        self.client.force_login(owner)
        resp = self.client.get('/exclusions/%d/' % char.pk)
        self.assertEqual(resp.status_code, 200)
        html = resp.content.decode('utf-8')
        items = json.loads(re.search(r'var allItems = (\{.*\});', html).group(1))
        names = json.loads(re.search(r'var allItemsNames = (\{.*\});', html).group(1))
        return set(items.keys()), names

    def test_every_forbiddable_name_maps_into_the_item_set(self):
        item_ids, names = self._load_forbid_data()
        bad = {n: i for n, i in names.items()
               if i is not None and str(i) not in item_ids}
        self.assertEqual(bad, {}, 'names point to non-forbiddable ids: %r' % bad)

    def test_gelano_is_forbiddable(self):
        item_ids, names = self._load_forbid_data()
        self.assertIn('Gelano', names)
        self.assertIn(str(names['Gelano']), item_ids)


class RobotsTxtTests(TestCase):
    """robots.txt keeps the public content crawlable and blocks the action
    endpoints and the per-project pages."""

    def _parser(self):
        import urllib.robotparser as rp
        body = self.client.get('/robots.txt').content.decode('utf-8')
        p = rp.RobotFileParser()
        p.parse(body.splitlines())
        return p, body

    def test_content_pages_stay_crawlable(self):
        p, _ = self._parser()
        for url in ['/', '/guides/getting-started/', '/encyclopedia/',
                    '/encyclopedia/item/equipment/123-foo/', '/sharedbuilds/',
                    '/s/zobal/abc123/', '/user/someone/', '/setup/', '/about/',
                    '/faq/', '/quickstart/', '/forgemagie/',
                    '/loadprojects/', '/compare_sets/s123/']:
            self.assertTrue(p.can_fetch('Googlebot', url),
                            'robots.txt must not block content page %s' % url)

    def test_action_endpoints_are_blocked(self):
        # The workshop is @login_required, so a crawler only ever gets /login/.
        p, _ = self._parser()
        for url in ['/setup/170414/', '/beta/setup/170414/', '/postcomment/3048/',
                    '/beta/postcomment/3048/', '/touch/saveprojecttouser/',
                    '/addtag/215413/', '/workshop/', '/workshop/addsolution/7420/',
                    '/loadproject/223687/', '/solution/123/', '/spells/123/',
                    '/exchange/5/', '/setitemlocked/1/', '/manageaccount/',
                    '/fashion/123/', '/inventory/', '/login/']:
            self.assertFalse(p.can_fetch('Googlebot', url),
                             'robots.txt must block action endpoint %s' % url)

    def test_sitemap_is_declared(self):
        _, body = self._parser()
        self.assertIn('Sitemap: https://dofusfashionista.gg/sitemap.xml', body)

    #: The list Cloudflare's managed robots.txt used to prepend. It reached the
    #: apex only, so www answered with the managed stub alone and none of the
    #: rules above were ever seen there. Serving them ourselves makes both
    #: hostnames answer the same thing -- and makes it testable, which the
    #: managed file was not.
    TRAINING_CRAWLERS = ('Amazonbot', 'Applebot-Extended', 'Bytespider',
                         'CCBot', 'ClaudeBot', 'Google-Extended', 'GPTBot',
                         'meta-externalagent')

    #: Fetch a page because a reader asked for them, and send that reader back.
    #: Blocking these would cost visits, so they must stay welcome.
    READER_ASSISTANTS = ('ChatGPT-User', 'Claude-User', 'PerplexityBot',
                         'OAI-SearchBot')

    def test_training_crawlers_are_blocked(self):
        p, _ = self._parser()
        for agent in self.TRAINING_CRAWLERS:
            self.assertFalse(
                p.can_fetch(agent, '/encyclopedia/item/equipment/44-x/'),
                'robots.txt must block the training crawler %s' % agent)

    def test_reader_assistants_stay_welcome(self):
        """Blocking a crawler that carries a reader here costs visits."""
        p, _ = self._parser()
        for agent in self.READER_ASSISTANTS:
            self.assertTrue(
                p.can_fetch(agent, '/encyclopedia/item/equipment/44-x/'),
                '%s brings readers and must not be blocked' % agent)

    def test_search_engines_are_untouched_by_the_ai_rules(self):
        """The blocked names share prefixes with the engines that matter.

        `Google-Extended` trains models; `Googlebot` sends visitors. A parser
        matching on a prefix would read the first rule as covering the second
        and deindex the site, so the distinction is asserted rather than
        assumed.
        """
        p, _ = self._parser()
        for agent in ('Googlebot', 'Googlebot-Image', 'Bingbot',
                      'Mediapartners-Google'):
            self.assertTrue(p.can_fetch(agent, '/encyclopedia/'),
                            '%s must keep crawling the public content' % agent)

    def test_content_signal_is_declared(self):
        """A machine-readable reservation of rights under article 4 of the EU
        directive 2019/790, and the site's answer to the question the training
        crawlers do not ask."""
        _, body = self._parser()
        self.assertIn('Content-Signal: search=yes,ai-train=no,use=reference',
                      body)


class DataPipelineImportsTests(SimpleTestCase):
    """The item pipeline must keep resolving its own paths.

    fashionista_config is imported under two different names: the site puts
    <repo>/fashionistapulp on sys.path (manage.py) and sees
    `fashionistapulp.fashionista_config`, while every data pipeline sets
    PYTHONPATH to the repo root (update_data.py) and sees
    `fashionistapulp.fashionistapulp.fashionista_config`. Code that only ever
    runs under the second layout is invisible to the rest of this suite, so a
    change can break every scraper while the whole suite stays green -- which is
    what happened when the version registry replaced the _DB_FILES and
    _DUMP_FILES dicts and two call sites kept reaching for them. Nothing failed
    loudly: the site kept serving the item database it already had, and each
    game patch would have made the encyclopedia quietly more wrong.

    Running a subprocess is the only way to observe that layout from here.
    """

    REPO = os.path.dirname(os.path.dirname(os.path.dirname(
        os.path.abspath(__file__))))
    NL = chr(10)

    def _run_as_pipeline(self, lines, extra_path=()):
        import subprocess
        chemins = (self.REPO,) + tuple(extra_path)
        prologue = ['import sys'] + [
            'sys.path.insert(0, %r)' % p for p in reversed(chemins)]
        return subprocess.run(
            [sys.executable, '-c', self.NL.join(prologue + list(lines))],
            capture_output=True, text=True, cwd=self.REPO)

    def test_config_resolves_every_version_in_the_pipeline_layout(self):
        done = self._run_as_pipeline([
            'from fashionistapulp.fashionistapulp.game_versions'
            ' import GAME_VERSIONS',
            'from fashionistapulp.fashionistapulp.fashionista_config'
            ' import get_items_db_path, get_items_dump_path',
            'for key in sorted(GAME_VERSIONS):',
            '    get_items_db_path(key)',
            '    get_items_dump_path(key)',
        ])
        self.assertEqual(
            done.returncode, 0,
            'fashionista_config is unusable from a data pipeline:' + self.NL
            + done.stdout + done.stderr)

    def test_the_scrapers_resolve_every_version(self):
        """store_item_obtainment feeds some 28 other scraper modules, so when
        it cannot resolve a path none of them can either."""
        done = self._run_as_pipeline([
            'import store_item_obtainment as s',
            'from fashionistapulp.fashionistapulp.game_versions'
            ' import GAME_VERSIONS',
            'for key in sorted(GAME_VERSIONS):',
            '    assert s.get_items_db_path(key).endswith(".db"), key',
            '    assert s.get_items_dump_path(key).endswith(".dump"), key',
        ], extra_path=(os.path.join(self.REPO, 'itemscraper'),))
        self.assertEqual(
            done.returncode, 0,
            'the item scrapers cannot resolve their paths:' + self.NL
            + done.stdout + done.stderr)

    def test_an_unknown_version_is_refused_rather_than_silently_dofus3(self):
        """Both getters used to answer an unknown name with Dofus 3's own
        database, so a typo served another game's items under the wrong name."""
        done = self._run_as_pipeline([
            'from fashionistapulp.fashionistapulp.fashionista_config'
            ' import get_items_db_path',
            'try:',
            '    get_items_db_path("no-such-version")',
            'except KeyError:',
            '    raise SystemExit(0)',
            'raise SystemExit("an unknown version was accepted")',
        ])
        self.assertEqual(done.returncode, 0, done.stdout + done.stderr)


