class SolveFromMyOwnItemsTests(TestCase):
    """"Only what I own" is a headline promise of the inventory: every piece the
    solver hands back has to come out of the folder. The mode is read from the
    options blob, which is one of the columns that now falls back to an empty
    value rather than raising, so the promise is worth pinning down."""

    def _project_with_folder(self, mode, owned_names):
        from django.test import RequestFactory
        from django.contrib.auth.models import User
        from fashionistapulp.structure import get_structure, set_current_game_version
        from chardata.coaching_view import create_build
        from chardata.models import InventoryFolder, InventoryItem
        from chardata.options import get_options, set_options
        set_current_game_version('dofus3')
        self.addCleanup(set_current_game_version, 'dofus3')
        structure = get_structure('dofus3')
        owner = User.objects.create_user('inv' + mode, '%s@t.local' % mode, 'pw-42-solid')
        request = RequestFactory().post('/')
        request.user = owner
        char = create_build(request, 'Iop', 200, {'str'}, 'dofus3')
        folder = InventoryFolder.objects.create(
            user=owner, name='mine', game_version='dofus3')
        owned = []
        for name in owned_names:
            item = structure.get_item_by_name(name)
            self.assertIsNotNone(item, name)
            InventoryItem.objects.create(folder=folder, item_id=item.id,
                                         custom_stats='')
            owned.append(item.name)
        options = get_options(char)
        options['inventory_mode'] = mode
        options['inventory_folder'] = folder.id
        set_options(char, options)
        self.client.force_login(owner)
        self.client.get('/fashion/%d/' % char.pk)
        char.refresh_from_db()
        return char, owned

    # A handful of real level 200 pieces, one per slot, plus a cheap weapon.
    OWNED = ['Baleenaboots', 'Suspender Belt', 'Jiva Necklace', 'Ochre Dofus']

    def test_only_what_i_own_equips_nothing_else(self):
        if not _pulp_solver_available():
            self.skipTest('no pulp solver available')
        from chardata.solution import get_solution
        char, owned = self._project_with_folder('only', self.OWNED)
        solution = get_solution(char)
        self.assertIsNotNone(solution)
        worn = [ri.name for ri in solution.item_list if ri.item_added]
        self.assertTrue(worn, 'the solver equipped nothing at all')
        self.assertEqual([], [name for name in worn if name not in owned],
                         'a piece came from outside the folder')

    def test_everything_mode_ignores_the_folder(self):
        if not _pulp_solver_available():
            self.skipTest('no pulp solver available')
        from chardata.solution import get_solution
        char, owned = self._project_with_folder('all', self.OWNED)
        worn = [ri.name for ri in get_solution(char).item_list if ri.item_added]
        self.assertTrue([name for name in worn if name not in owned],
                        'with the whole game allowed, the build should not be '
                        'limited to the four owned pieces')


class OwnedOrItemStaysEquippableTests(TestCase):
    """An item gated behind alternative conditions ships as several rows sharing
    one name, and the solver forbids the whole group as soon as one row is
    forbidden. A folder holds the single row the item picker offers, so
    excluding the other rows used to take the owned one down with them: 44 Retro
    items and 20 Touch ones sat in a folder that could not equip them."""

    def _or_group(self, structure):
        groups = {}
        for item in structure.get_concatenated_items_lists():
            groups.setdefault((item.dofus_touch, item.or_name), []).append(item)
        for (_dt, name), members in sorted(groups.items(),
                                           key=lambda kv: str(kv[0][1])):
            if len(members) > 1 and name != 'Gelano':
                return name, members
        return None, []

    def _excluded_ids(self, version, owned_ids):
        from django.test import RequestFactory
        from django.contrib.auth.models import User
        from fashionistapulp.structure import set_current_game_version
        from chardata.coaching_view import create_build
        from chardata.models import InventoryFolder, InventoryItem
        from chardata.inventory_solver import apply_inventory_restriction
        set_current_game_version(version)
        self.addCleanup(set_current_game_version, 'dofus3')
        owner = User.objects.create_user(
            'orinv' + version, '%s@t.local' % version, 'pw-42-solid')
        request = RequestFactory().post('/')
        request.user = owner
        char = create_build(request, 'Iop', 200, {'str'}, version)
        folder = InventoryFolder.objects.create(
            user=owner, name='mine', game_version=version)
        for item_id in owned_ids:
            InventoryItem.objects.create(folder=folder, item_id=item_id,
                                         custom_stats='')
        return set(apply_inventory_restriction(char, [], folder))

    def _assert_group_survives(self, version):
        from fashionistapulp.structure import get_structure, set_current_game_version
        set_current_game_version(version)
        self.addCleanup(set_current_game_version, 'dofus3')
        structure = get_structure(version)
        name, members = self._or_group(structure)
        self.assertIsNotNone(name, '%s has no OR-grouped item to check' % version)
        # The picker offers the group under the id of its first row.
        excluded = self._excluded_ids(version, [members[0].id])
        still_forbidden = sorted(m.name for m in members if m.id in excluded)
        self.assertEqual([], still_forbidden,
                         'owning %s left rows of it excluded' % name)

    def test_retro_keeps_every_row_of_an_owned_or_item(self):
        self._assert_group_survives('retro')

    def test_touch_keeps_every_row_of_an_owned_or_item(self):
        self._assert_group_survives('touch')

    def test_an_or_item_nobody_owns_stays_excluded(self):
        from fashionistapulp.structure import get_structure, set_current_game_version
        set_current_game_version('retro')
        self.addCleanup(set_current_game_version, 'dofus3')
        structure = get_structure('retro')
        name, members = self._or_group(structure)
        self.assertIsNotNone(name)
        excluded = self._excluded_ids('retro', [])
        missing = sorted(m.name for m in members if m.id not in excluded)
        self.assertEqual([], missing,
                         'an unowned group must stay out of the pool')


class PublicEntryPointsSurviveNonsenseTests(TestCase):
    """Every 500 this site has had was on a public URL and was found by a
    player. These four were not reachable from any link, which is why the page
    sweep never walked into them."""

    def test_the_dead_error_route_is_gone(self):
        # util_views.error takes five arguments and the URLconf could supply
        # one, so it raised before its first line for any value, on all five
        # version prefixes. Nothing linked to it and nothing reversed it.
        for prefix in ('', '/beta', '/dofus2', '/retro', '/touch'):
            with self.subTest(prefix=prefix or '/'):
                self.assertEqual(
                    self.client.get('%s/error/1/' % prefix).status_code, 404)

    def test_the_api_page_number_cannot_become_a_bad_offset(self):
        # page_size was clamped and page only had a floor, and the value lands
        # in a slice that the ORM inlines as a literal SQL OFFSET.
        for page in ('999999999999999999', '99999999999999999999', '-5',
                     'abc'):
            with self.subTest(page=page):
                resp = self.client.get(
                    '/api/v1/shared-builds/?page=%s' % page)
                self.assertEqual(resp.status_code, 200)

    def test_a_wild_level_does_not_reach_the_integer_field(self):
        # The sibling path, coaching_view.create_build, clamps the same value.
        for level in ('99999999999999999999', '-99999999999999999999', '0'):
            with self.subTest(level=level):
                resp = self.client.post('/createproject/', {
                    'project': 'p-%s' % level[:6], 'charname': 'c',
                    'level': level, 'class': 'Iop'})
                self.assertIn(resp.status_code, (200, 302))

    def test_the_order_rows_parameter_is_bounded(self):
        # Each row draws a full stat select, so an 8 KB URL asked for 9 MB.
        import json

        control = len(self.client.get('/encyclopedia/').content)
        payload = json.dumps([{} for _ in range(880)])
        resp = self.client.get('/encyclopedia/',
                               {'order_rows_json': payload})
        self.assertEqual(resp.status_code, 200)
        self.assertLess(
            len(resp.content), control * 3,
            'the page grew to %d bytes from a %d byte parameter'
            % (len(resp.content), len(payload)))


class OgUrlAgreesWithTheCanonicalTests(TestCase):
    """og:url used request.path, which drops the query string, while a
    paginated encyclopedia canonical carries ?page=N and a version-prefixed
    static page points its canonical at the unprefixed copy. The two tags on
    one page named two different URLs."""

    PAGES = ('/about/', '/faq/', '/guides/', '/license/', '/privacy/',
             '/support/', '/', '/contact/', '/encyclopedia/?page=2',
             '/encyclopedia/monsters/?page=3')

    def test_the_two_tags_name_the_same_url_on_every_version(self):
        import re

        # The minifier sorts attributes alphabetically, in the test client too:
        # href lands before rel and content before property, so the tag is
        # matched first and the attribute read out of it.
        href = re.compile(r'href="([^"]*)"')
        content = re.compile(r'content="([^"]*)"')

        checked = 0
        for prefix in ('', '/retro', '/beta', '/dofus2', '/touch'):
            for page in self.PAGES:
                url = prefix + page
                resp = self.client.get(url)
                if resp.status_code != 200:
                    continue
                head = resp.content.decode('utf-8').split('</head>')[0]

                found = None
                for element in re.findall(r'<link[^>]*>', head):
                    if 'rel="canonical"' in element:
                        match = href.search(element)
                        if match:
                            found = match.group(1)
                        break

                shown = None
                for element in re.findall(r'<meta[^>]*>', head):
                    if 'property="og:url"' in element:
                        match = content.search(element)
                        if match:
                            shown = match.group(1)
                        break

                if not found or not shown:
                    continue
                checked += 1
                with self.subTest(url=url):
                    self.assertEqual(found, shown)
        self.assertGreater(checked, 20,
                           'only %d pages carried both tags' % checked)

    def test_no_template_comment_leaks_into_the_page(self):
        # {# #} is single-line only. A two-line one ships as text, and on
        # base.html it closed </head> early, which is how og:url ended up in
        # the body. The monster page has the same guard; the shell had none.
        for url in ('/', '/about/', '/faq/', '/encyclopedia/', '/contact/'):
            with self.subTest(url=url):
                body = self.client.get(url).content.decode('utf-8')
                self.assertNotIn('{#', body)
                self.assertNotIn('#}', body)


class MobileStackingStaysOutOfDataTablesTests(SimpleTestCase):
    """The rule that stacks an image-and-text table on a phone said so in its
    own comment, then used a descendant combinator and reached every cell of
    every nested table. Under 900px the four builds compared side by side
    collapsed into one unlabelled column."""

    def _modern_css(self):
        import io as _io
        import os
        here = os.path.dirname(os.path.abspath(__file__))
        with _io.open(os.path.join(here, 'static', 'chardata', 'modern.css'),
                      encoding='utf-8') as handle:
            return handle.read()

    def test_the_cell_rule_takes_direct_children_only(self):
        css = self._modern_css()
        stacking = [line for line in css.split('\n')
                    if ':has(img)' in line and 'display:block' in line
                    and ' td{' in line]
        self.assertTrue(stacking, 'the stacking rule is gone entirely')
        for line in stacking:
            self.assertIn('> tbody > tr > td{', line,
                          'a descendant combinator reaches nested tables: %s'
                          % line.strip()[:110])

    def test_the_project_list_is_treated_as_a_data_table(self):
        self.assertIn('not(.load-project-table)', self._modern_css())


class RobotsAgreesWithTheSitemapTests(TestCase):
    """robots.txt blocked */setup/ while sitemap-pages.xml submitted the four
    version-prefixed setup pages, which answer 200 and say index, follow."""

    def test_every_setup_page_the_sitemap_submits_is_allowed(self):
        robots = self.client.get('/robots.txt').content.decode('utf-8')
        self.assertIn('Allow: /setup/$', robots)
        self.assertIn('Allow: /*/setup/$', robots)
        for prefix in ('', '/beta', '/dofus2', '/retro', '/touch'):
            with self.subTest(prefix=prefix or '/'):
                resp = self.client.get('%s/setup/' % prefix)
                self.assertEqual(resp.status_code, 200)

    def test_nothing_the_sitemap_submits_is_blocked(self):
        """The pair the class is named for, checked in the other direction.

        Reading the file and reading the sitemap are two answers to the same
        question, and a rule added to save crawl budget is exactly the kind
        that shuts a door nobody meant to shut. Parsed with the standard
        library rather than by matching strings: the file has ninety Disallow
        lines and a wildcard among them is not something to reason about.
        """
        import re
        import urllib.robotparser

        parser = urllib.robotparser.RobotFileParser()
        parser.parse(self.client.get('/robots.txt')
                     .content.decode('utf-8').splitlines())

        index = self.client.get('/sitemap.xml').content.decode('utf-8')
        blocked = []
        checked = 0
        for sitemap in re.findall(r'<loc>([^<]+)</loc>', index):
            path = re.sub(r'^https?://[^/]+', '', sitemap)
            body = self.client.get(path).content.decode('utf-8')
            # A sample per file: reading 151 905 urls here would trade a
            # useful guard for a slow one. But the sample is SPREAD, not
            # the first 25: a sitemap is ordered, so its opening entries
            # are the same static pages every time. The one url this
            # guard did not catch -- a shared build named 'fashion',
            # blocked by `Disallow: */fashion/` written for the solver
            # endpoint -- sits well past the twenty-fifth line. Same
            # cost, and the sample now touches the whole file.
            toutes = re.findall(r'<loc>([^<]+)</loc>', body)
            pas = max(1, len(toutes) // 25)
            for url in toutes[::pas][:25]:
                checked += 1
                if not parser.can_fetch('Googlebot', url):
                    blocked.append(url)
        self.assertFalse(
            blocked, '%d submitted urls are blocked by robots.txt: %s'
            % (len(blocked), blocked[:5]))
        self.assertGreater(checked, 100, 'checked only %d urls' % checked)

    def test_the_random_build_redirect_is_not_crawled(self):
        """It answers a different build every time, so there is nothing to
        index and nothing stable to return to. The builds it points at are
        submitted by name in sitemap-pages.xml, so blocking it costs no
        discovery."""
        import urllib.robotparser

        parser = urllib.robotparser.RobotFileParser()
        parser.parse(self.client.get('/robots.txt')
                     .content.decode('utf-8').splitlines())
        for prefix in ('', '/beta', '/dofus2', '/retro', '/touch', '/fr'):
            with self.subTest(prefix=prefix or '/'):
                self.assertFalse(parser.can_fetch(
                    'Googlebot',
                    'https://dofusfashionista.gg%s/random/' % prefix))


class ACapIsWhatTheSheetShowsTests(TestCase):
    """13 AP of gear is equippable on Dofus 3 and the sheet reads 12; Retro has
    no cap and reads 13. The model used to bound the stat variable at the cap
    and tie that same variable to the gear, which made the cap a rule about
    what could be WORN: the solver spent a slot on a -1 AP weapon to get back
    under 12, and answered Infeasible when no such piece existed."""

    def test_the_shown_total_never_passes_the_cap(self):
        from fashionistapulp.structure import (get_structure,
                                               set_current_game_version)
        from fashionistapulp.modelresult import ModelResult
        from fashionistapulp.dofus_constants import get_stat_maximum

        set_current_game_version('dofus3')
        structure = get_structure('dofus3')
        ap_key = 'ap'
        cap = get_stat_maximum('dofus3')['AP']

        # Six pieces carrying AP, more than the cap allows to show.
        wearing = []
        for type_name, slot in (('Hat', 'hat'), ('Cloak', 'cloak'),
                                ('Belt', 'belt'), ('Boots', 'boots'),
                                ('Amulet', 'amulet'), ('Ring', 'ring1')):
            for item in structure.get_unique_items_by_type_and_level(
                    type_name, 200):
                stats = {structure.get_stat_by_id(sid).key: value
                         for sid, value in item.stats}
                if stats.get(ap_key, 0) >= 1:
                    wearing.append((slot, item))
                    break

        self.assertGreaterEqual(len(wearing), 4,
                                'not enough AP pieces to build the case')

        result = ModelResult({'options': {'ap_exo': False, 'mp_exo': False,
                                          'range_exo': False},
                              'base_stats_by_attr': {'AP': 7},
                              'char_level': 200}, None)
        for slot, item in wearing:
            result.add_item_at_slot(item, slot)

        gear = result.get_stats_gear()[ap_key]
        shown = result.get_stats_total()[ap_key]
        self.assertGreater(gear + 7, cap,
                           'the case does not exceed the cap, so it proves '
                           'nothing')
        self.assertEqual(shown, cap,
                         'the sheet shows %s AP where the game shows %s'
                         % (shown, cap))

    def test_retro_has_no_cap_so_nothing_is_clamped(self):
        from fashionistapulp.dofus_constants import get_stat_maximum
        self.assertNotIn('AP', get_stat_maximum('retro'))
        self.assertEqual(get_stat_maximum('dofus3')['AP'], 12)

    def test_the_model_lets_the_gear_pass_the_cap(self):
        # The variable the gear is tied to must not carry the cap any more.
        import re

        repo_root = os.path.dirname(
            os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
        path = os.path.join(repo_root, 'fashionistapulp', 'fashionistapulp',
                            'model.py')
        with io.open(path, encoding='utf-8') as handle:
            source = handle.read()
        self.assertIn("head = 'total' if stat.name in self.stat_maximum", source,
                      'the gear sum is tied to the capped variable again')
        self.assertIn('def create_stat_cap_constraints', source)


class OwnedExoCountsOnlyWhenWornTests(TestCase):
    """Two different things used to be merged into one. The wizard option means
    "assume I have an AP exo somewhere" and adds +1 whatever the build wears.
    An exo recorded on one owned item means that item gives the point, so it
    counts only when the item is equipped. Recording one used to switch the
    option on, which handed every build a free AP, including builds that do not
    and cannot wear the item."""

    def test_a_recorded_exo_marks_the_piece_that_carries_it(self):
        # The piece keeps its catalogue AP: the extra point is worth one for
        # the whole build, so it is a variable of its own and the piece is only
        # what makes it available.
        from fashionistapulp.structure import get_structure
        from fashionistapulp.model import Model

        structure = get_structure('dofus3')
        hat = next(item for item
                   in structure.get_unique_items_by_type_and_level('Hat', 200)
                   if not item.removed and not any(
                       structure.get_stat_by_id(sid).key == 'ap'
                       for sid, _value in item.stats))
        ap_id = structure.get_stat_by_key('ap').id

        model = Model.__new__(Model)
        model.structure = structure
        model.items_list = [hat]
        model._apply_stat_overrides({hat.id: {ap_id: 1}})

        self.assertNotIn(ap_id, dict(model.items_list[0].stats),
                         'the exo was baked into the piece, so two exo pieces '
                         'worn together would give the build two points')
        self.assertIn(hat.id, model._exo_carriers['ap'],
                      'nothing records that this piece can provide the point')

    def test_two_exo_pieces_worn_together_still_give_one_point(self):
        # Several exo pieces can be worn; AP, MP and Range gain one point each
        # whatever their number, and a piece worn beyond that is worn without
        # its exo counting.
        from fashionistapulp.structure import get_structure
        from fashionistapulp.modelresult import ModelResult

        structure = get_structure('dofus3')
        hats = [item for item
                in structure.get_unique_items_by_type_and_level('Hat', 200)
                if not item.removed][:1]
        belts = [item for item
                 in structure.get_unique_items_by_type_and_level('Belt', 200)
                 if not item.removed][:1]
        ap_id = structure.get_stat_by_key('ap').id
        overrides = {hats[0].id: {ap_id: 99}, belts[0].id: {ap_id: 99}}

        result = ModelResult({'options': {'ap_exo': False, 'mp_exo': False,
                                          'range_exo': False},
                              'base_stats_by_attr': {}, 'char_level': 200},
                             None)
        result.add_item_at_slot(hats[0], 'hat', overrides)
        result.add_item_at_slot(belts[0], 'belt', overrides)

        carried = sum(dict(item.stats).get(ap_id, 0)
                      for item in (hats[0], belts[0]))
        self.assertEqual(result.get_stats_gear()['ap'], carried + 1,
                         'two exo pieces gave the build more than one point')

    def test_recording_an_exo_does_not_switch_the_option_on(self):
        from django.contrib.auth.models import User
        from django.test import RequestFactory
        from fashionistapulp.structure import (set_current_game_version,
                                               get_structure)
        from chardata.coaching_view import create_build
        from chardata.models import InventoryFolder, InventoryItem
        from chardata.options import get_options, set_options

        set_current_game_version('dofus3')
        structure = get_structure('dofus3')
        hat = next(item for item
                   in structure.get_unique_items_by_type_and_level('Hat', 200)
                   if not item.removed)

        owner = User.objects.create_user('ownedexo', 'oe@test.local',
                                         'pw-42-solid')
        request = RequestFactory().post('/')
        request.user = owner
        char = create_build(request, 'Iop', 200, {'str'}, 'dofus3')

        folder = InventoryFolder.objects.create(user=owner, name='inv',
                                                game_version='dofus3')
        InventoryItem.objects.create(folder=folder, item_id=hat.id,
                                     custom_stats='{"ap": 1}')
        options = get_options(char)
        options['ap_exo'] = False
        options['inventory_mode'] = 'mixed'
        options['inventory_folder'] = folder.id
        set_options(char, options)

        self.client.force_login(owner)
        self.client.get('/fashion/%d/' % char.pk)

        self.assertFalse(get_options(char)['ap_exo'],
                         'an exo recorded on one hat turned on the option that '
                         'gives every build a free AP')


class GelanoExoInventoryTests(TestCase):
    """MP exo "only Gelano" must equip the +1 AP +1 MP Gelano, not the plain one."""

    @unittest.skipUnless(_pulp_solver_available(), 'no pulp solver available')
    def test_gelano_exo_keeps_the_mp_gelano_despite_an_owned_mp_roll(self):
        import pickle as _pickle
        from django.test import RequestFactory
        from django.contrib.auth.models import User
        from fashionistapulp.structure import set_current_game_version, get_structure
        from chardata.coaching_view import create_build
        from chardata.options import get_options, set_options
        from chardata.models import InventoryFolder, InventoryItem
        from chardata.solution import get_solution
        set_current_game_version('dofus3')
        structure = get_structure('dofus3')
        gelano2 = structure.get_item_by_name('Gelano (#2)')
        boots = next(it for it in structure.get_concatenated_items_lists()
                     if it.type == structure.get_type_id_by_name('Boots'))
        owner = User.objects.create_user('gelexo', 'ge@test.local', 'pw-gel-77')
        req = RequestFactory().post('/')
        req.user = owner
        char = create_build(req, 'Xelor', 150, {'cha'}, 'dofus3')
        folder = InventoryFolder.objects.create(
            user=owner, name='inv', game_version='dofus3')
        InventoryItem.objects.create(folder=folder, item_id=gelano2.id, custom_stats='')
        # An owned item with an MP roll above its base.
        InventoryItem.objects.create(
            folder=folder, item_id=boots.id, custom_stats='{"mp": 3}')
        options = get_options(char)
        options['mp_exo'] = 'gelano'
        options['inventory_mode'] = 'only'
        options['inventory_folder'] = folder.id
        set_options(char, options)
        self.client.force_login(owner)
        self.client.get('/fashion/%d/' % char.pk)
        char.refresh_from_db()
        solution = get_solution(char)
        gelanos = [ri for ri in solution.item_list
                   if ri.item_added and 'Gelano' in getattr(ri, 'name', '')]
        self.assertEqual(len(gelanos), 1, 'expected a Gelano equipped')
        self.assertEqual(gelanos[0].stats.get('mp'), 1,
                         'gelano exo must equip the +1 MP Gelano, not the plain one')


