    def test_touch_monster_page_shows_official_grade_stats(self):
        # Touch grades come from the Touch backend Monsters table (monster_grades).
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path

        conn = sqlite3.connect(get_items_db_path('touch'))
        try:
            rows = conn.execute(
                """SELECT grade, level, life_points FROM monster_grades
                   WHERE monster_ankama_id = 101 ORDER BY grade""").fetchall()
        finally:
            conn.close()
        self.assertTrue(rows, 'no touch grades stored for the Gobball')

        resp = self.client.get('/touch/encyclopedia/monster/101-bouftou/',
                               HTTP_ACCEPT_LANGUAGE='fr')
        self.assertEqual(resp.status_code, 200)
        body = resp.content.decode('utf-8')
        self.assertIn('id="monster-stats"', body)
        self.assertIn('Caractéristiques par grade', body)
        for grade, level, hp in rows:
            self.assertIn('<td>%d</td>' % level, body)
            self.assertIn('<td>%d</td>' % hp, body)

        # dofus3 grades come from DofusDB: same monster id, its own numbers.
        conn = sqlite3.connect(get_items_db_path('dofus3'))
        try:
            d3_rows = conn.execute(
                """SELECT grade, level, life_points FROM monster_grades
                   WHERE monster_ankama_id = 101 ORDER BY grade""").fetchall()
        finally:
            conn.close()
        self.assertTrue(d3_rows, 'no dofus3 grades stored for the Gobball')
        self.assertNotEqual(rows, d3_rows,
                            'touch and dofus3 grades must be version-specific')
        resp = self.client.get('/encyclopedia/monster/101-bouftou/')
        self.assertEqual(resp.status_code, 200)
        body = resp.content.decode('utf-8')
        self.assertIn('id="monster-stats"', body)
        self.assertIn('<td>%d</td>' % d3_rows[0][1], body)

        # retro has its own 1.29 numbers from the Solomonk bestiary.
        conn = sqlite3.connect(get_items_db_path('retro'))
        try:
            retro_rows = conn.execute(
                """SELECT grade, level, life_points FROM monster_grades
                   WHERE monster_ankama_id = 101 ORDER BY grade""").fetchall()
        finally:
            conn.close()
        self.assertTrue(retro_rows, 'no retro grades stored for the Gobball')
        self.assertNotEqual(retro_rows, d3_rows,
                            'retro and dofus3 grades must be version-specific')
        resp = self.client.get('/retro/encyclopedia/monster/101-bouftou/')
        self.assertEqual(resp.status_code, 200)
        body = resp.content.decode('utf-8')
        self.assertIn('id="monster-stats"', body)
        self.assertIn('<td>%d</td>' % retro_rows[0][1], body)

        # dofus2 grades come from the 2.73 archive it already downloads.
        conn = sqlite3.connect(get_items_db_path('dofus2'))
        try:
            d2_rows = conn.execute(
                """SELECT grade, level, life_points FROM monster_grades
                   WHERE monster_ankama_id = 101 ORDER BY grade""").fetchall()
        finally:
            conn.close()
        self.assertTrue(d2_rows, 'no dofus2 grades stored for the Gobball')
        resp = self.client.get('/dofus2/encyclopedia/monster/101-bouftou/')
        self.assertEqual(resp.status_code, 200)
        body = resp.content.decode('utf-8')
        self.assertIn('id="monster-stats"', body)
        self.assertIn('<td>%d</td>' % d2_rows[0][1], body)

    def test_no_spell_description_keeps_the_client_markup(self):
        # The tooltip escapes what it is given, so a reader was shown the
        # client's own markup: "Pushes back 6 cells{{~zs}}", "1 <sprite
        # name=\"PA\"> AP used", and a spell link written
        # "{{spell,24510,1::<color=#ebc304>Telefrag</color>}}".
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path

        for game_version in ('dofus3', 'beta', 'dofus2', 'touch', 'retro'):
            conn = sqlite3.connect(get_items_db_path(game_version))
            try:
                if not conn.execute(
                        "SELECT 1 FROM sqlite_master WHERE type = 'table' "
                        "AND name = 'monster_spell_names'").fetchone():
                    continue
                total = conn.execute(
                    'SELECT COUNT(*) FROM monster_spell_names').fetchone()[0]
                bad = conn.execute(
                    "SELECT spell_ankama_id, language, description "
                    "FROM monster_spell_names "
                    "WHERE description LIKE '%{{%' OR description LIKE '%<%' "
                    "LIMIT 5").fetchall()
            finally:
                conn.close()
            self.assertGreater(total, 0, 'no spell names stored for %s'
                                         % game_version)
            self.assertFalse(bad, '%s keeps client markup, first few: %s'
                                  % (game_version, bad[:3]))

    def test_the_agreement_markup_takes_the_form_the_count_asks_for(self):
        # ~p is what a plural adds and ~s what a singular adds; ~z is a second
        # slot that no label in the dump carries without ~p, and ~f and ~m are
        # a gender a spell line never names. An empty payload inside a marker
        # takes the next segment's, which is how "{{~p~zies}}" spells
        # territories.
        import importlib.util

        repo_root = os.path.dirname(
            os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
        path = os.path.join(repo_root, 'itemscraper', 'store_monster_spells.py')
        spec = importlib.util.spec_from_file_location('store_monster_spells',
                                                      path)
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)

        cases = (
            ('Pushes back #1 cell{{~ps}}{{~zs}}', 1, 'Pushes back 1 cell'),
            ('Pushes back #1 cell{{~ps}}{{~zs}}', 6, 'Pushes back 6 cells'),
            ('Repousse de #1 case{{~ps}}{{~zs}}', 1, 'Repousse de 1 case'),
            ('Repousse de #1 case{{~ps}}{{~zs}}', 4, 'Repousse de 4 cases'),
            ('#1 Diplomat{{~m}}{{~fin}}', 1, '1 Diplomat'),
        )
        for template, count, expected in cases:
            with self.subTest(template=template, count=count):
                self.assertEqual(
                    module.render_effect(template, count, 0), expected)

        # The two shapes that are not about a count at all.
        self.assertEqual(
            module.strip_display_markup(
                'Can generate a '
                '{{spell,24510,1::<color=#ebc304>Telefrag</color>}}.'),
            'Can generate a Telefrag.')
        self.assertEqual(
            module.strip_display_markup(
                '200 Neutral damage for 1 <sprite name="PA"> AP used'),
            '200 Neutral damage for 1 AP used')

    def test_no_version_stores_an_unusable_grade_row(self):
        # A row with no level or no life points is not a grade: it renders as
        # dashes and drags the published range down. Every source has produced
        # one. DofusDB keeps unused duplicates of real monsters (id 246
        # Arachnee, all grades level 1 with 0 hp, while the real one is id 52
        # at 16-20); the Touch backend ships placeholders; the Retro bestiary
        # built its grade set as a union over every stat, which gave Tofu Royal
        # a sixth grade at 0 hp and a 0-5000 range. The AP and MP columns held
        # -1 and -100 sentinels on four versions, published raw.
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path

        for game_version in ('dofus3', 'beta', 'dofus2', 'touch', 'retro'):
            conn = sqlite3.connect(get_items_db_path(game_version))
            try:
                if not conn.execute(
                        "SELECT 1 FROM sqlite_master "
                        "WHERE type = 'table' AND name = 'monster_grades'"
                        ).fetchone():
                    continue
                total = conn.execute(
                    'SELECT COUNT(*) FROM monster_grades').fetchone()[0]
                bad = conn.execute(
                    'SELECT monster_ankama_id, grade, level, life_points, '
                    'action_points, movement_points FROM monster_grades '
                    'WHERE life_points IS NULL OR life_points <= 0 '
                    'OR level IS NULL OR level <= 0 '
                    # -1 and -100 are the client's way of saying a creature
                    # does not move. 0 AP or 0 MP is a real creature.
                    'OR action_points < 0 OR movement_points < 0 '
                    'LIMIT 5').fetchall()
            finally:
                conn.close()
            self.assertGreater(total, 0,
                               'no monster grades stored for %s' % game_version)
            self.assertFalse(bad, '%s stores empty grade rows, first few: %s'
                                  % (game_version, bad[:3]))

    def test_monster_hub_shows_level_ranges_per_version(self):
        # The level span comes from each version's own monster_grades table.
        import re
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path

        for prefix, version in (('/touch', 'touch'), ('/retro', 'retro'),
                                ('/dofus2', 'dofus2'), ('', 'dofus3')):
            conn = sqlite3.connect(get_items_db_path(version))
            try:
                level_min, level_max = conn.execute(
                    """SELECT MIN(level), MAX(level) FROM monster_grades
                       WHERE monster_ankama_id = 101 AND level IS NOT NULL""").fetchone()
            finally:
                conn.close()
            self.assertIsNotNone(level_min, version)
            resp = self.client.get('%s/encyclopedia/monsters/?q=bouftou' % prefix,
                                   HTTP_ACCEPT_LANGUAGE='fr')
            self.assertEqual(resp.status_code, 200, version)
            body = resp.content.decode('utf-8')
            expected = ('Niveau %d-%d' % (level_min, level_max)
                        if level_max != level_min else 'Niveau %d' % level_min)
            self.assertIn(expected, re.sub(r'\s+', ' ', body), version)

        resp = self.client.get('/touch/encyclopedia/monsters/?sort=level',
                               HTTP_ACCEPT_LANGUAGE='fr')
        self.assertEqual(resp.status_code, 200)
        body = re.sub(r'\s+', ' ', resp.content.decode('utf-8'))
        self.assertEqual(resp.context['sort_key'], 'level')
        self.assertIn('value="level"', body)
        mins = [int(m) for m in re.findall(r'Niveau (\d+)', body)]
        self.assertTrue(mins, 'no level lines rendered on the sorted hub')
        self.assertEqual(mins, sorted(mins))

