class WeaponWithoutApTests(TestCase):
    """Retro ships four weapons the game itself gives no combat data to, so
    they reach the rating with no AP cost. Dividing the damage by it took the
    whole weapon list down, sorted by damage, on every Retro build."""

    NO_AP_IDS = (2170, 3358, 6455, 8093)

    def test_the_four_retro_weapons_still_carry_no_ap(self):
        from fashionistapulp.structure import get_structure, set_current_game_version
        self.addCleanup(set_current_game_version, 'dofus3')
        set_current_game_version('retro')
        structure = get_structure('retro')
        for item_id in self.NO_AP_IDS:
            item = structure.get_item_by_id(item_id)
            with self.subTest(item=item_id):
                self.assertIsNotNone(item)
                weapon = structure.get_weapon_by_name(item.name)
                self.assertIsNotNone(weapon)
                self.assertIsNone(weapon.ap)

    def test_no_other_version_hides_a_weapon_without_ap(self):
        import sqlite3
        from fashionistapulp.fashionista_config import get_items_db_path
        tables = ('weapon_hits', 'weapon_crit_bonus', 'weapon_crit_hits',
                  'weapon_weapontype')
        for version in ('dofus3', 'beta', 'dofus2', 'touch'):
            conn = sqlite3.connect(get_items_db_path(version))
            try:
                seen = set()
                for table in tables:
                    seen |= {row[0] for row in conn.execute(
                        'SELECT DISTINCT item FROM %s' % table)}
                with_ap = {row[0] for row in conn.execute(
                    'SELECT item FROM weapon_ap')}
            finally:
                conn.close()
            with self.subTest(version=version):
                self.assertTrue(seen)
                self.assertEqual(sorted(seen - with_ap), [])

    def test_a_weapon_with_no_ap_rates_zero_rather_than_raising(self):
        import collections
        from unittest import mock
        from chardata.item_exchange import _get_weapon_rate

        class Hitless(object):
            ap = None
            has_crits = False
            crit_chance_percent = 0
            non_crit_hits = collections.defaultdict(list)
            crit_hits = collections.defaultdict(list)

        class Pool(object):
            is_mageable = False

        class Solution(object):
            stats_total = {'ch': 0}

            def switch_item(self, item, slot, overrides=None):
                return Pool()

        class Named(object):
            name = 'Mercenary\'s Sword'

        with mock.patch('chardata.item_exchange.get_structure') as structure:
            structure.return_value.get_weapon_by_name.return_value = Hitless()
            self.assertEqual(_get_weapon_rate(Named(), None, Solution()), 0)

    def test_a_header_without_an_ap_cost_states_what_is_known(self):
        from chardata.weapon_header import format_weapon_header
        # Retro: no cost and no crit, which is all four of them.
        self.assertEqual('(Sword)',
                         format_weapon_header('retro', 'Sword', None, -1, -1))
        # Nothing known at all: no line rather than an empty one.
        self.assertEqual('', format_weapon_header('retro', None, None, -1, -1))
        # A cost we do not have must not silence a rate we do have.
        self.assertEqual('(Bow) CH: 1/30 (+5)',
                         format_weapon_header('retro', 'Bow', None, 30, 5))
        self.assertEqual('(Bow) CH: 25% (+5)',
                         format_weapon_header('dofus3', 'Bow', None, 25, 5))

    def test_every_weapon_of_every_version_formats(self):
        from fashionistapulp.structure import get_structure, set_current_game_version
        from chardata.weapon_header import format_weapon_header
        self.addCleanup(set_current_game_version, 'dofus3')
        for version in ('dofus3', 'beta', 'dofus2', 'touch', 'retro'):
            set_current_game_version(version)
            structure = get_structure(version)
            weapons = (list(structure.weapons_dict_by_name.items())
                       + list(structure.dt_weapons_dict_by_name.items()))
            self.assertTrue(weapons, version)
            for name, weapon in weapons:
                try:
                    format_weapon_header(version, 'Sword', weapon.ap,
                                         weapon.crit_chance, weapon.crit_bonus)
                except Exception as error:
                    self.fail('%s %s: %s' % (version, name, error))

    def test_their_encyclopedia_pages_answer(self):
        # The item page uses the same formatter, but only for a weapon that has
        # hits, and these four have none: they were never a 500 there. Pinned
        # because the page is where the picker sends a player.
        for item_id in self.NO_AP_IDS:
            with self.subTest(item=item_id):
                resp = self.client.get(
                    '/retro/encyclopedia/item/equipment/%d-x/' % item_id)
                self.assertEqual(resp.status_code, 200)

    def test_the_weapon_picker_survives_a_weapon_with_no_ap(self):
        # The player's request, from the 17/08 report: the weapon list ordered
        # by damage with a search term that reaches one of the four.
        resp = self.client.post('/retro/itemexchange/%d/' % self.char.pk,
                                {'slot': 'weapon', 'page': '1',
                                 'order_by_stat': 'true',
                                 'search_term': 'Mercenary'})
        self.assertEqual(resp.status_code, 200)
        self.assertIn('Mercenary', resp.content.decode('utf-8'))

    def setUp(self):
        from django.contrib.auth.models import User
        from chardata.models import Char
        import _pickle
        from fashionistapulp.modelresult import ModelResultMinimal
        user = User.objects.create_user('noap', 'noap@test.local', 'pw-42-solid')
        input_ = {'char_class': 'Iop', 'char_level': 200, 'origin': 'generated',
                  'options': {'ap_exo': False, 'mp_exo': False},
                  'base_stats_by_attr': {'Vitality': 0, 'Wisdom': 0,
                                         'Strength': 0, 'Intelligence': 0,
                                         'Chance': 0, 'Agility': 0},
                  'locked_equips': {}}
        self.char = Char.objects.create(
            name='No AP', char_name='no-ap', char_class='Iop',
            char_build='Damage', level=200, minimum_stats=b'',
            minimum_crits=b'', stats_weight=b'', options=b'', inclusions=b'',
            exclusions=b'',
            minimal_solution=_pickle.dumps(ModelResultMinimal({}, input_, {})),
            owner=user, link_shared=False, game_version='retro')
        self.client.force_login(user)


class ExclusionsPostTests(TestCase):
    """The exclusion list arrives as a JSON string of item ids. A request with
    no list raised ValidationError straight out of the view, and one whose list
    is not JSON, or not a list of numbers, raised out of json or int: 500 on all
    five versions for a request the page never sends and a stale tab does."""

    def setUp(self):
        from django.contrib.auth.models import User
        from chardata.models import Char
        self.user = User.objects.create_user('excl', 'excl@test.local',
                                             'pw-42-solid')
        self.char = Char.objects.create(
            name='Excl', char_name='excl', char_class='Iop',
            char_build='build', level=200, minimum_stats=b'',
            minimum_crits=b'', stats_weight=b'', options=b'', inclusions=b'',
            exclusions=b'', owner=self.user, link_shared=False,
            game_version='dofus3')
        self.client.force_login(self.user)

    def _post(self, payload):
        return self.client.post('/exclusionspost/%d/' % self.char.pk, payload)

    def test_a_missing_list_is_a_bad_request(self):
        self.assertEqual(400, self._post({}).status_code)

    def test_a_list_that_is_not_a_list_of_ids_is_a_bad_request(self):
        for raw in ('not json', '{"a": 1}', '5', 'null', '[1, "x"]', '[[]]'):
            with self.subTest(exclusions=raw):
                self.assertEqual(400, self._post({'exclusions': raw}).status_code)

    def test_a_real_list_is_still_saved(self):
        import json
        from fashionistapulp.structure import get_structure, set_current_game_version
        from chardata.lock_forbid import get_all_exclusions_ids
        self.addCleanup(set_current_game_version, 'dofus3')
        set_current_game_version('dofus3')
        structure = get_structure('dofus3')
        boots_type = structure.get_type_id_by_name('Boots')
        boots = next(i for i in structure.get_concatenated_items_lists()
                     if i.type == boots_type and not i.removed)
        resp = self._post({'exclusions': json.dumps([boots.id])})
        self.assertEqual(200, resp.status_code)
        self.char.refresh_from_db()
        self.assertIn(boots.id, get_all_exclusions_ids(self.char))


